window.PROGRAMMES = {"source":"https://www.ifrap.org/comparateurs/presidentielles-2027","extractedAt":"2026-10-01","candidates":[{"id":"10620","first":"Nathalie","last":"Arthaud","party":"Lutte Ouvrière","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-09/nathalie_arthaud_lo_19-05-2024.jpg?h=b41e208e&itok=AQjYT2mx","pos":-9.5},{"id":"7804","first":"Gabriel","last":"Attal","party":"LREM","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/abaca_991816_019.jpg?h=42bc9e86&itok=5YOKt9oC","pos":1.5},{"id":"53","first":"Xavier","last":"Bertrand","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/import/qtgdcs-v_400x400.jpg?h=a7e6d17b&itok=NJQg5OlE","pos":4},{"id":"10361","first":"Bernard","last":"Cazeneuve","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-08/bc.jpg?h=8a7fc05e&itok=FOyXmNk4","pos":-2.5},{"id":"10536","first":"Nicolas","last":"Dupont-Aignan","party":"Debout la France","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-09/nicolas_dupont-aignan_homme_politique_francais_cropped.jpg?h=c0e21fb8&itok=KMWlN98D","pos":7},{"id":"10357","first":"Olivier","last":"Faure","party":"PS","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-08/20260830205906-9122712_0.jpg?h=04d92ac6&itok=g9eDLsKs","pos":-4},{"id":"7806","first":"Raphaël","last":"Glucksmann","party":"Place publique","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/abaca_974903_125.jpg?h=f44d63db&itok=K-Hz9d36","pos":-3},{"id":"8413","first":"Jérôme","last":"Guedj","party":"PS","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/biographie-e1681143832706.jpg?h=07d56b28&itok=gg6EegNB","pos":-4.5},{"id":"37","first":"François","last":"Hollande","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/import/fh.jpeg?h=db5f1bc6&itok=W2RhlG-Z","pos":-3},{"id":"8254","first":"Marine","last":"Le Pen","party":"RN","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-07/000-b9jt4wr-1.jpg?h=c12e0b96&itok=fTk0y3Tf","pos":7.5},{"id":"8039","first":"David","last":"Lisnard","party":"LR","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/david-lisnard-hero-v2.jpg?h=331e80e9&itok=b6oDvoO3","pos":5.5},{"id":"10767","first":"Emmanuel","last":"Maurel","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-09/842271.jpg?h=f5652cad&itok=5rgps-8v","pos":-6},{"id":"65","first":"Jean-Luc","last":"Mélenchon","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/import/jean_luc_melenchon.jpg?h=8c387ee1&itok=02mjb1wb","pos":-7.5},{"id":"7805","first":"Edouard","last":"Philippe","party":"Horizons","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/abaca_993338_013.jpg?h=58c8a5e7&itok=O_Ho7LKJ","pos":3},{"id":"7803","first":"Bruno","last":"Retailleau","party":"LR","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/abaca_987299_006_2.jpg?h=8c1344d8&itok=AGga66SF","pos":6},{"id":"14","first":"Fabien","last":"Roussel","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/import/frous.jpg?h=a7e6d17b&itok=mrjVsSPS","pos":-7},{"id":"10360","first":"Ségolène","last":"Royal","party":"PS","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-08/sego_r.jpeg?h=031b01a4&itok=AsptvYLy","pos":-3.5},{"id":"8455","first":"François","last":"Ruffin","party":"","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-04/x61hh9hg_400x400.jpg?h=a7e6d17b&itok=l9c8clzI","pos":-6.5},{"id":"8038","first":"Marine","last":"Tondelier","party":"EELV","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/38nqtq9-avebnlgsfqvvef.jpg?h=a1e1a043&itok=SaOO6QT0","pos":-5.5},{"id":"8298","first":"Éric","last":"Zemmour","party":"Reconquête !","photo":"https://www.ifrap.org/sites/default/files/styles/96x96/public/images/2026-03/90.jpeg?h=eed40179&itok=hU7t3M3o","pos":9}],"themes":[{"id":"636","name":"Finances publiques","subs":[{"id":"641","name":"Economies & hausses de dépenses","ideas":[{"id":"641-1","c":"7804","t":"Baisser les charges sur le travail par des économies (grâce à l’assurance chômage notamment)."},{"id":"641-2","c":"7804","t":"Proposer une grande loi de programmation économique et fiscale sur 10 ans afin de donner de la visibilité aux acteurs économiques."},{"id":"641-3","c":"7804","t":"Faire des réformes de structure : changer le système de retraite, mettre fin à la spirale des arrêts maladie, faire la réforme de l’assurance chômage pour rapporter 5 Md€ d’économies."},{"id":"641-4","c":"7804","t":"Avoir une impunité zéro pour ceux qui gèrent le budget. Les ministres et directeurs d’administration centrale qui n’auront pas tenu leur budget devront quitter leur fonction."},{"id":"641-5","c":"7804","t":"Faire un projet de loi de finances rectificative dès les premiers mois après l’élection."},{"id":"641-6","c":"7804","t":"Faire une année blanche sur l’ensemble des prestations sociales pour le budget 2028 sans toucher aux petites retraites."},{"id":"641-7","c":"7804","t":"Supprimer 100 000 postes de fonctionnaires. Economies : plus de 7Md€, grâce à un plan de départs volontaires, sans toucher aux ministères de l’éducation nationale, des armées, de la justice et de l’intérieur."},{"id":"641-8","c":"7804","t":"Créer de nouvelles collectivités uniques pour faire des économies au niveau de l’organisation territoriale de l’État."},{"id":"641-9","c":"10357","t":"Organiser une conférence salariale tripartie avec l'Etat, les syndicats et le patronat pour conditionner les aides publiques aux entreprises aux salaires, à la bifurcation écologique, à la formation des salariés."},{"id":"641-10","c":"10357","t":"Etablir une règle selon laquelle pour 1 € de dividende distribué, au moins 1 € soit versé aux salariés sous forme de participation, d'intéressement, ou de salaire."},{"id":"641-11","c":"7806","t":"2,3 à 3 Md€ d'économies sur le fonctionnement de l'Etat, et notamment la gestion foncière."},{"id":"641-12","c":"7806","t":"Rediriger 211 Md€ d'exonérations et aides aux entreprises."},{"id":"641-13","c":"7806","t":"Tripler le chèque énergie pour faire face à la hausse des prix du carburant. Cibler les mesures d'aide sur les classes populaires et moyennes qui ont besoin de leur voiture pour aller travailler."},{"id":"641-14","c":"8413","t":"Faire des économies sur la Sécurité sociale tout en assurant la meilleure prise en charge pour les assurés, en supprimant les dépenses redondantes, les gaspillages et rentes."},{"id":"641-15","c":"10767","t":"Proposer aux Français, et notamment aux séniors qui ont beaucoup d'épargne disponible, de participer à un grand plan d'investissement pour décarboner et électrifier : contracter un emprunt national citoyen grâce aux 6 000 Md€ d'épargne disponible en France."},{"id":"641-16","c":"65","t":"Bloquer les prix des produits de première nécessité, notamment du carburant et de l’énergie."},{"id":"641-17","c":"65","t":"Revenir sur les privatisations (aéroports, autoroutes, Française des jeux, etc)."},{"id":"641-18","c":"65","t":"Rendre effectif le droit de réquisition des usines et entreprises d’intérêt général par l’État."},{"id":"641-19","c":"65","t":"Moduler l’impôt sur les sociétés selon l’usage des bénéfices pour encourager l’investissement en France et pénaliser le versement de dividendes."},{"id":"641-20","c":"65","t":"Interdire aux entreprises de distribuer un montant de dividendes supérieur à leurs bénéfices."},{"id":"641-21","c":"65","t":"Mettre fin à la cotation continue des entreprises en Bourse et moduler les droits de vote des actionnaires selon la durée d’engagement dans l’entreprise."},{"id":"641-22","c":"65","t":"Interdire les licenciements boursiers et économiques par les entreprises qui versent des dividendes ou bénéficient des aides de l’État."},{"id":"641-23","c":"65","t":"Favoriser le développement des sociétés coopératives d’intérêt collectif (SCIC) et les sociétés coopératives et participatives (SCOP) de façon à développer des services communs dont la responsabilité est partagée entre citoyens et usagers, salariés, partenaires publics et privés."},{"id":"641-24","c":"65","t":"Développer les coopératives d’activités et d’emploi (CAE) afin de lutter contre le statut d’autoentrepreneur et de développer des formes de travail en commun."},{"id":"641-25","c":"65","t":"Instaurer une première tranche gratuite de consommation d’électricité, de chaleur, d’eau, de gaz."},{"id":"641-26","c":"65","t":"Restructurer les emprunts des ménages surendettés et garantir à tous l’accès effectif aux services bancaires de base."},{"id":"641-27","c":"65","t":"Plafonner les frais bancaires."},{"id":"641-28","c":"65","t":"Indexer les prix des produits de première nécessité et interdire la « réduflation »."},{"id":"641-29","c":"7805","t":"Mettre en place un « Deal fiscal » de 250 Mds d’€ pour les entreprises : baisser de 50 Md€ les impôts de production par an pendant 5 ans (cela représente 250 Md€ sur un quinquennat), et supprimer 50Md€ d'aides publiques improductives pour créer un choc de compétitivité."},{"id":"641-30","c":"7805","t":"Inscrire une « règle d’or » budgétaire dans la Constitution, soit une obligation constitutionnelle à limiter le déficit public, « hors dépenses militaires ». Ramener le déficit à 2 % du PIB sur le quinquennat."},{"id":"641-31","c":"7805","t":"Stabiliser les dépenses de santé en misant sur la prévention et les transformations technologiques."},{"id":"641-32","c":"7803","t":"Redresser les finances publiques de 120 Md€ d'ici 2032 uniquement par la baisse des dépenses et sans hausses d'impôts autres que celles annoncées en juillet 2025 par le gouvernement."},{"id":"641-33","c":"7803","t":"Baisser de 10% et recentrer les crédits de l’aide publique au développement (APD) : 1,2 Md€ d’économies."},{"id":"641-34","c":"7803","t":"Ne pas remplacer systématiquement les agents publics partants à la retraite pour les fonctions supports. Objectif : améliorer la productivité par l’usage de l’IA pour supprimer 250 000 à 300 000 postes sur le quinquennat, avec des redéploiements d’agents sur le terrain."},{"id":"641-35","c":"7803","t":"Baisser les dotations aux agences de l’État."},{"id":"641-36","c":"7803","t":"Baisser le nombre de bénéficiaires de l’AME, et réduire le panier de soins couvert."},{"id":"641-37","c":"10360","t":"Supprimer les aides aux entreprises injustifiées."},{"id":"641-38","c":"10360","t":"Réformer en profondeur le fonctionnement de l'Etat :\n• supprimer les superpositions de strates administratives,\n• supprimer les conseils, hauts comités et hauts commissariats,\n• diminuer le train de vie de l'Etat et des institutions européennes."},{"id":"641-39","c":"10360","t":"Aligner les salaires des employés des entreprises publiques sur ceux de la fonction publique."},{"id":"641-40","c":"10360","t":"Réorganiser les administrations en fonction des territoires."},{"id":"641-41","c":"8298","t":"Ne plus accorder de subventions publiques aux associations politisées dont le militantisme nuit à l’intérêt général, et ce selon trois critères : si l’association promeut des actions illégales (comme l’immigration clandestine), si l’association entrave l’action de l’État, et si l’association prend parti pour un camp politique."},{"id":"641-42","c":"8298","t":"Lancer un grand audit de la Cour des comptes sur toutes les politiques publiques."},{"id":"641-43","c":"8298","t":"Rétablir les corps préfectoral et diplomatique supprimés dans le cadre de la réforme de la haute fonction publique initiée en 2021."},{"id":"641-44","c":"8298","t":"Revenir sur les trois jours de carence pour les arrêts maladie des agents de la fonction publique."},{"id":"641-45","c":"8298","t":"Réduire le nombre d’élus locaux en rétablissant le conseiller territorial (siégeant à la fois au conseil départemental et au conseil régional) sur le modèle de la réforme de 2010."}]},{"id":"637","name":"Dette & déficit","ideas":[{"id":"637-46","c":"7804","t":"Atteindre 0 % du PIB du déficit public à horizon 2037, avec un premier point d’étape à 3 % avant 2032 pour un montant d’économies de 120 à 150 milliards à réaliser sur cette période."},{"id":"637-47","c":"7804","t":"Inscrire une règle d’or budgétaire dans la Constitution, sur le modèle allemand."},{"id":"637-48","c":"65","t":"Exiger de l’UE que la Banque centrale européenne transforme la part de dette des États qu’elle possède en dettes perpétuelles à taux nul."},{"id":"637-49","c":"65","t":"Faire racheter par la BCE la dette publique qui circule sur les marchés financiers sans passer par les banques privées et mettre en place une autorisation de découvert des États auprès de la BCE, afin de sortir le financement de l’État de la main des marchés financiers."},{"id":"637-50","c":"65","t":"Réinstaurer un circuit du Trésor pour sortir la dette publique de la main des marchés financiers en rendant obligatoire la détention d’une part minimum de leurs fonds propres en bons du trésor français par les établissements bancaires exerçant en France."},{"id":"637-51","c":"65","t":"Mettre fin à l’émission de titres de dette souveraine indexés sur l’inflation (OATi)."},{"id":"637-52","c":"65","t":"Retirer la dette Covid des comptes de la Sécurité sociale, réformer la Caisse d’amortissement de la dette sociale."},{"id":"637-53","c":"7805","t":"Inscrire dans la Constitution une « règle d’or » budgétaire pour limiter les déficits publics en empêchant l’État de financer les dépenses courantes par la dette."},{"id":"637-54","c":"7805","t":"Ramener le déficit à 2 % du PIB en fin de quinquennat soit en 2032."},{"id":"637-55","c":"7803","t":"Mettre en place une règle d’or dans le cadre de la révision constitutionnelle soumise à référendum dès 2027."}]},{"id":"581","name":"Fiscalité","ideas":[{"id":"581-56","c":"7804","t":"Baisser de 2 Md€ les impôts pour les classes moyennes."},{"id":"581-57","c":"7804","t":"Baisser de façon ciblée les impôts plutôt qu’entreprendre une réforme fiscale globale."},{"id":"581-58","c":"7804","t":"Baisser les impôts de production."},{"id":"581-59","c":"10357","t":"Appliquer la taxe Zucman."},{"id":"581-60","c":"7806","t":"Mettre en place un chantier fiscal pour rééquilibrer la répartition de la taxation entre le travail, le capital, l’héritage et les retraites."},{"id":"581-61","c":"7806","t":"Supprimer les exonérations de TVA et de taxe sur le kérosène."},{"id":"581-62","c":"7806","t":"Taxer les méga héritages, au-dessus de 2 millions d'euros."},{"id":"581-63","c":"7806","t":"Instaurer un impôt plancher annuel de 2% sur les patrimoines supérieurs à 100 millions d'euros (taxe Zucman)."},{"id":"581-64","c":"7806","t":"Mettre en place une taxation des plus hauts patrimoines à l'échelle européenne pour éviter l'exil fiscal."},{"id":"581-65","c":"7806","t":"Baisser les cotisations sociales pour rapprocher le salaire brut du net grâce à une taxation des gros héritages."},{"id":"581-66","c":"7806","t":"Réviser le pacte Dutreil pour éviter l'optimisation fiscale dans les grandes holdings."},{"id":"581-67","c":"7806","t":"Récupérer 15 Md€ par an sur la \"Grande transmission\" ( 9 000 Md€ transmis en France d'ici 2040), pour baisser la CSG et permettre que sur un salaire de 2 000 euros net, un salarié récupère 120 euros supplémentaires."},{"id":"581-68","c":"8413","t":"Baisser les taxes sur le carburant de manière transitoire."},{"id":"581-69","c":"8413","t":"Réintroduire un impôt sur la fortune (ISF) climatique pour financer notamment l'électrification."},{"id":"581-70","c":"8413","t":"Conditionner les exonérations de cotisations sociales pour les entreprises à leurs choix en matière de versement de dividendes, du temps que leurs employés passent au SMIC etc."},{"id":"581-71","c":"37","t":"Mettre à contribution les patrimoines supérieurs à 10 millions d'euros lors de la transmission pour financer des mesures sociales."},{"id":"581-72","c":"37","t":"Supprimer la TVA sur les produits alimentaires et les travaux de rénovation énergétique, en passant de 5,5 % à 0 %."},{"id":"581-73","c":"37","t":"Baisser les cotisations salariales pour augmenter le salaire net d'environ 10 %, financé par une hausse de 4 points de la TVA."},{"id":"581-74","c":"8254","t":"Créer l'impôt sur la fortune financière (IFF), inspiré de l’ancien ISF, mais excluant la résidence principale (ou une résidence secondaire au choix)."},{"id":"581-75","c":"8039","t":"Baisser la fiscalité sur les héritages et les donations afin de faciliter la transmission du patrimoine."},{"id":"581-76","c":"8039","t":"Augmenter les abattements sur les donations, jugés aujourd’hui insuffisants, pour permettre aux parents de transmettre davantage à leurs enfants de leur vivant."},{"id":"581-77","c":"8039","t":"Permettre à chacun de transmettre son patrimoine aux personnes de son choix, au-delà de sa famille, mais aussi à des fonds de capitalisation ou à des causes d’intérêt général."},{"id":"581-78","c":"10767","t":"Rééquilibrer la fiscalité pour faire entrer davantage de recettes fiscales."},{"id":"581-79","c":"65","t":"Instaurer une taxe sur les transactions financières."},{"id":"581-80","c":"65","t":"Refonder l’impôt sur les sociétés pour établir l’égalité devant l’impôt entre PME et grands groupes, instaurer un barème progressif en fonction des bénéfices réalisés et selon leur usage et favoriser l’investissement plutôt que la distribution de dividendes."},{"id":"581-81","c":"65","t":"Rétablir et renforcer l’impôt de solidarité sur la fortune (ISF), incluant un volet climatique visant à taxer les gros pollueurs."},{"id":"581-82","c":"65","t":"Instaurer un impôt plancher annuel de 2% sur les patrimoines supérieurs à 100 millions d'euros (taxe Zucman)."},{"id":"581-83","c":"65","t":"Supprimer la flat tax et imposer les revenus du capital comme ceux du travail."},{"id":"581-84","c":"65","t":"Rendre la CSG progressive avec 14 tranches."},{"id":"581-85","c":"65","t":"Augmenter les droits de succession sur les plus hauts patrimoines en comptabilisant l’ensemble des dons et héritages reçus tout au long de la vie et créer un héritage maximal de 12M€."},{"id":"581-86","c":"65","t":"Baisser la TVA sur les produits de première nécessité de 5,5 % à 5 %. Créer une TVA à 21,6 % sur les produits de « grand luxe » afin de compenser la baisse de TVA sur les produits de première nécessité."},{"id":"581-87","c":"65","t":"Instaurer un impôt universel sur les entreprises et sur les revenus des particuliers pour lutter contre l’évasion fiscale."},{"id":"581-88","c":"65","t":"Rétablir l’exit tax supprimée par Emmanuel Macron."},{"id":"581-89","c":"65","t":"Établir une taxe permanente sur les superprofits étendue à l’ensemble des secteurs d’activité, pas uniquement au secteur énergétique."},{"id":"581-90","c":"65","t":"Refonder la taxe foncière pour la rendre progressive et que chacun paie à hauteur de son patrimoine total réel."},{"id":"581-91","c":"65","t":"Mettre fin au quotient conjugal, système patriarcal favorisant les inégalités salariales entre les femmes et les hommes, remplacer l’injuste quotient familial fiscal actuel par un crédit d’impôt par enfant que pourraient toucher toutes les familles."},{"id":"581-92","c":"65","t":"Mettre fin à la convention judiciaire d’intérêt public."},{"id":"581-93","c":"65","t":"Rendre obligatoire pour les entreprises la publication des aides publiques qu’elles perçoivent."},{"id":"581-94","c":"7805","t":"Défendre le pacte Dutreil."},{"id":"581-95","c":"7805","t":"Augmenter les plafonds d'exonération fiscale des donations pendant les trois premières années du quinquennat."},{"id":"581-96","c":"7805","t":"Favoriser la transmission anticipée du patrimoine de son vivant."},{"id":"581-97","c":"7805","t":"Conclure un pacte fiscal avec les entreprises pour produire un choc de compétitivité : baisser de 50 Md€ les impôts de production et supprimer 50 Md€ d'aides publiques improductives."},{"id":"581-98","c":"7805","t":"S'engager à ne pas créer de nouvel impôt sur le quinquennat."},{"id":"581-99","c":"7805","t":"Accorder une part fiscale dès le deuxième enfant."},{"id":"581-100","c":"7803","t":"Rehausser le seuil d’exonération des donations à 150 000 euros."},{"id":"581-101","c":"7803","t":"Réduire de 40 milliards d’euros les cotisations sociales afin de diminuer le coût du travail pour les entreprises."},{"id":"581-102","c":"7803","t":"Exonérer totalement de cotisations sociales les heures supplémentaires effectuées au-delà de 35 heures par semaine, afin de rendre les heures supplémentaires plus avantageuses pour les salariés et moins coûteuses pour les employeurs."},{"id":"581-103","c":"14","t":"Rétablir l'ISF (impôt sur la fortune) et tripler son montant."},{"id":"581-104","c":"14","t":"Rendre l'impôt sur le revenu plus progressif en portant son nombre de tranches à 15."},{"id":"581-105","c":"14","t":"Faire disparaître progressivement la CSG (Contribution sociale généralisée) en transférant son financement vers les cotisations sociales des entreprises."},{"id":"581-106","c":"14","t":"Créer un registre public des bénéficiaires effectifs des entreprises, afin de lutter contre les pratiques d'optimisation fiscale agressive."},{"id":"581-107","c":"14","t":"Créer un nouvel impôt sur les sociétés (IS) progressif, dont le taux varierait selon le chiffre d'affaires et les bénéfices des entreprises. Le taux serait également plus élevé pour les groupes qui délocalisent des activités, suppriment des emplois, réalisent certaines opérations financières ou provoquent des pollutions."},{"id":"581-108","c":"10360","t":"Rétablir l'impôt de solidarité sur la fortune financière pour un rendement évalué entre 3 et 4 Md€."},{"id":"581-109","c":"10360","t":"Baisser les taxes sur le carburant et notamment la TVA pour garantir un prix à 1,70 euro du litre jusqu'au mois de décembre. Le manque à gagner fiscal évalué à 5 Md€ devrait être inférieur au coût économique pour les entreprises, les familles etc."},{"id":"581-110","c":"10360","t":"Demander une dérogation à la Commission européenne comme l'a fait l'Espagne pour baisser l'accise sur le gasoil de 33 centimes."},{"id":"581-111","c":"10360","t":"Supprimer le certificat d'économie d'énergie acquitté sur le prix du carburant, qui revient à une mesure d'écologie punitive."},{"id":"581-112","c":"8455","t":"Organiser des États généraux de la fiscalité : grande consultation nationale pour refondre le système fiscal."},{"id":"581-113","c":"8455","t":"Lutter contre l’évasion fiscale pour mettre fin aux stratégies d’évitement de l’impôt."},{"id":"581-114","c":"8038","t":"Renforcer la fiscalité sur les successions en instaurant une contribution de 10 % sur les héritages dépassant 4 millions d’euros, puis de 10 % supplémentaires au-delà de 13 millions d’euros."},{"id":"581-115","c":"8038","t":"Abaisser de 75 % à 50 % l’exonération prévue par le pacte Dutreil."},{"id":"581-116","c":"8038","t":"Supprimer les avantages fiscaux liés au démembrement de propriété."},{"id":"581-117","c":"8038","t":"Instaurer un impôt plancher de 2 % sur le patrimoine des contribuables dont la fortune dépasse 100 millions d’euros (taxe Zucman)."},{"id":"581-118","c":"8038","t":"Rétablir un ISF avec une dimension climatique, afin de taxer les hauts patrimoines en fonction de leur impact environnemental."},{"id":"581-119","c":"8298","t":"Augmenter le salaire des travailleurs modestes du public, du privé et des indépendants par la baisse de la CSG."},{"id":"581-120","c":"8298","t":"Permettre aux chefs d’entreprises de récompenser leurs salariés en instaurant une prime \"zéro charge\"."}]},{"id":"603","name":"Secteur bancaire & finance","ideas":[{"id":"603-121","c":"65","t":"Séparer les banques d’affaires et de détail."},{"id":"603-122","c":"65","t":"Contrôler les mouvements de capitaux."},{"id":"603-123","c":"65","t":"Limiter les LBO (rachat d’une entreprise par une société qui recourt à l’emprunt) aux seules procédures de reprise des entreprises par les salariés."},{"id":"603-124","c":"65","t":"Créer un pôle public bancaire."},{"id":"603-125","c":"65","t":"Socialiser certaines banques de détail et les intégrer au pôle public bancaire, en vue de financer les très petites entreprises sur des critères sociaux et écologiques et d’alimenter le budget public."},{"id":"603-126","c":"65","t":"Dépolluer les flux financiers, en pénalisant la détention et l’usage d’actifs financiers nocifs climatiquement et écologiquement et en renchérissant le crédit pour les entreprises dont la comptabilité carbone n’est pas en conformité avec l’Accord de Paris."},{"id":"603-127","c":"65","t":"Créer une caisse de péréquation interentreprises financée grâce à un barème progressif pour mutualiser la contribution sociale entre petites et grandes entreprises."},{"id":"603-128","c":"7803","t":"Réorienter l’épargne des Français vers l’économie productive, notamment vers les fonds propres des entreprises françaises, l’industrie et les secteurs stratégiques."},{"id":"603-129","c":"7803","t":"Réformer la fiscalité et les supports d’épargne pour favoriser l’investissement productif de long terme et réorienter progressivement une partie des flux aujourd’hui consacrés à la dette publique ou au logement social."},{"id":"603-130","c":"7803","t":"Orienter prioritairement cette épargne longue vers l’économie réelle : PME, industrie, infrastructures productives et secteurs stratégiques."},{"id":"603-131","c":"7803","t":"Constituer à terme environ 1 000 Md€ de capital productif, afin de financer la réindustrialisation et de renforcer la soutenabilité du système de retraite."},{"id":"603-132","c":"8038","t":"Orienter le pôle public bancaire (Caisse des dépôts, BPI, …) vers la transition sociale et écologique."},{"id":"603-133","c":"8038","t":"Proposer un taux zéro pour les projets d’énergie renouvelable."},{"id":"603-134","c":"8038","t":"Réduire la part des actifs fossiles."},{"id":"603-135","c":"8038","t":"Adopter un Community Reinvestment Act."}]}]},{"id":"634","name":"Intérieur & Justice","subs":[{"id":"584","name":"Immigration","ideas":[{"id":"584-136","c":"7804","t":"Privilégier une immigration de travail."},{"id":"584-137","c":"7804","t":"Restreindre le regroupement familial."},{"id":"584-138","c":"7804","t":"Faire voter au Parlement des quotas d’immigration par secteur d’activité."},{"id":"584-139","c":"7804","t":"Mettre en place un permis à points pour l’immigration sur le modèle canadien."},{"id":"584-140","c":"10536","t":"Sortir de Schengen et recruter 10 000 agents spécialisés."},{"id":"584-141","c":"10536","t":"Limiter strictement le regroupement familial et supprimer les privilèges accordés aux algériens."},{"id":"584-142","c":"10536","t":"Créer des quotas d'étudiants étrangers par filière et par niveau."},{"id":"584-143","c":"10536","t":"Remise immédiate des mineurs isolés ou non accompagnés aux autorités de leur pays d'origine."},{"id":"584-144","c":"10536","t":"Conditionner l'immigration économique au taux de chômage."},{"id":"584-145","c":"10536","t":"Supprimer l'AME."},{"id":"584-146","c":"10536","t":"Supprimer les aides sociales non contributives pour les étrangers ( RSA, allocations familiales, aides au logement, etc.)."},{"id":"584-147","c":"10536","t":"Supprimer le droit du sol par référendum."},{"id":"584-148","c":"10536","t":"Limiter le droit de vote aux personnes qui possèdent la nationalité française."},{"id":"584-149","c":"7806","t":"Créer des voies légales et sécurisées d’immigration de travail et passer des accords bilatéraux avec les pays d’origine, liant la délivrance de visas multi-entrées pour des mobilités circulaires et la réadmission via des laissez-passer consulaires en cas de refus de séjour ou d’asile."},{"id":"584-150","c":"7806","t":"Abroger la loi immigration de 2024."},{"id":"584-151","c":"7806","t":"Généraliser la carte de séjour pluriannuelle en en faisant le titre de séjour de référence."},{"id":"584-152","c":"7806","t":"Mettre fin au système de la politique du chiffre sur les OQTF, et appliquer celles délivrées."},{"id":"584-153","c":"7805","t":"Faire voter au Parlement chaque année une liste de « pays sûrs » pour le droit d’asile."},{"id":"584-154","c":"7805","t":"Restreindre l'immigration familiale."},{"id":"584-155","c":"7805","t":"Mettre en place une politique de quotas migratoires permettant de choisir notre immigration économique."},{"id":"584-156","c":"7805","t":"Expulser immédiatement les étrangers délinquants et mettre fin à leurs aides sociales."},{"id":"584-157","c":"7805","t":"Utiliser les centres de retour prévus par la le réglement européen retour."},{"id":"584-158","c":"7805","t":"Mettre en place une véritable politique d'intégration par la langue, le travail et les valeurs républicaines."},{"id":"584-159","c":"7805","t":"Dénoncer l'accord de 1968 avec l'Algérie pour reprendre le contrôle des flux migratoires Algérie/France."},{"id":"584-160","c":"7803","t":"Permettre une immigration de travail avec un plus grand contrôle."},{"id":"584-161","c":"8298","t":"Supprimer le droit au « regroupement familial » et tous les droits automatiques liés à l’immigration familiale."},{"id":"584-162","c":"8298","t":"Revenir à l’esprit originel du droit d’asile en le limitant à une centaine d’individus chaque année (contre près de 140 000 aujourd’hui)."},{"id":"584-163","c":"8298","t":"Exiger que les demandes d’asile soient déposées en dehors du territoire national, dans nos consulats, pour éviter l’installation des déboutés."},{"id":"584-164","c":"8298","t":"Instaurer une caution obligatoire de 10 000 euros pour l’obtention d’un visa pour les étrangers provenant de pays dont sont majoritairement issus les immigrés clandestins, afin de limiter les entrées et de financer les éventuelles reconduites à la frontière."},{"id":"584-165","c":"8298","t":"Dénoncer les accords bilatéraux, en particulier l’accord franco-algérien de 1968."},{"id":"584-166","c":"8298","t":"Créer une garde-frontière à statut militaire pour épauler la police aux frontières du pays."},{"id":"584-167","c":"8298","t":"Combattre les passeurs en étendant la définition pénale de la traite des êtres humains."},{"id":"584-168","c":"8298","t":"Financer des campagnes d’information dans les pays d’origine visant à décourager les départs."},{"id":"584-169","c":"8298","t":"Supprimer les aides sociales non-contributives (allocations familiales, aides au logement, RSA, minimum vieillesse…) pour les étrangers extra-européens."},{"id":"584-170","c":"8298","t":"Supprimer les soins gratuits pour les étrangers clandestins (AME) pour ne conserver qu’une Aide médicale d’urgence (AMU)."},{"id":"584-171","c":"8298","t":"Interdire définitivement la régularisation de tout étranger entré illégalement sur le territoire français."},{"id":"584-172","c":"8298","t":"Supprimer le droit du sol."},{"id":"584-173","c":"8298","t":"Durcir les conditions de naturalisation, en augmentant la durée minimale de résidence en France de 5 ans à 10 ans, en exigeant une parfaite maitrise de la langue, une assimilation réelle, ainsi qu’une absence totale de condamnation judiciaire."},{"id":"584-174","c":"8298","t":"Réinstaurer le délit de séjour irrégulier supprimé en 2012."},{"id":"584-175","c":"8298","t":"Expulser systématiquement tous les délinquants étrangers dès leur condamnation et les criminels à l’issue de leur peine."},{"id":"584-176","c":"8298","t":"Expulser les étrangers au chômage au terme d’un délai de six mois de recherche d’emploi infructueuse."},{"id":"584-177","c":"8298","t":"Créer un ministère de la Remigration doté de tous les moyens matériels nécessaires, notamment des avions."}]},{"id":"657","name":"Justice & pénitentiaire","ideas":[{"id":"657-178","c":"7804","t":"Interdire le voile pour les moins de 15 ans."},{"id":"657-179","c":"7804","t":"Créer un délit de contrainte au port du voile."},{"id":"657-180","c":"7804","t":"Reprendre la réforme de la justice des mineurs qui n'avait pas été adoptée, et notamment les mesures pour rendre possible\n• la comparution immédiate pour les mineurs,\n• l'atténuation de l'excuse de minorité."},{"id":"657-181","c":"7804","t":"Faire évoluer notre justice pénale des mineurs qui permet aujourd'hui de reconnaître la culpabilité d'une jeune mais avec une sanction qui intervient trop tardivement, ce qui envoie un message d'impunité."},{"id":"657-182","c":"10536","t":"Créer 40 000 nouvelles places de prison."},{"id":"657-183","c":"10536","t":"Recruter 20 000 surveillants supplémentaires."},{"id":"657-184","c":"10536","t":"Rétablir l'uniforme de prisonnier."},{"id":"657-185","c":"10536","t":"Placer les maisons d'arrêt et les agents du service pénitentiaire sous l'autorité du ministère de l'Intérieur."},{"id":"657-186","c":"10536","t":"Installer partout des dispositifs de brouillage intégral des téléphones et d'interception des drones."},{"id":"657-187","c":"10536","t":"Remettre en vigueur les fouilles systématiques après chaque visite."},{"id":"657-188","c":"10536","t":"Faire contribuer les détenus au coût de leur incarcération."},{"id":"657-189","c":"7806","t":"Lancer un programme d’intervention rapide pour prévenir la délinquance avec des équipes mobiles."},{"id":"657-190","c":"7806","t":"Alléger les tâches administratives des policiers et gendarmes."},{"id":"657-191","c":"7806","t":"Revoir l’architecture de la Police avec, pour la police nationale, la suppression de l’échelon zonal, afin de renforcer les capacités opérationnelles réelles."},{"id":"657-192","c":"7806","t":"Renforcer les moyens d’enquête contre le narcotrafic."},{"id":"657-193","c":"7806","t":"Mettre en place un plan national de sécurité routière contre les comportements à risque axé sur cinq priorités : vitesse, alcool, drogues, usagers vulnérables, mobilités."},{"id":"657-194","c":"7806","t":"Renforcer la lutte contre le terrorisme, juger en France les djihadistes rapatriés, empêcher toute reformation de sanctuaires à l’étranger, et mettre en place une nouvelle stratégie nationale de lutte contre toutes les formes de radicalisation."},{"id":"657-195","c":"7806","t":"Doubler le nombre de Maisons du droit et de la justice."},{"id":"657-196","c":"7806","t":"Augmenter les effectifs des services judiciaires et pénitentiaires et les revaloriser."},{"id":"657-197","c":"8254","t":"Atteindre 85 000 places de prison disponibles d'ici à 2028."},{"id":"657-198","c":"8039","t":"Supprimer les réductions de peine automatiques."},{"id":"657-199","c":"8039","t":"Mettre fin aux aménagements dès l’audience."},{"id":"657-200","c":"8039","t":"Rétablir les peines planchers pour les récidivistes."},{"id":"657-201","c":"8039","t":"Appliquer systématiquement une sanction."},{"id":"657-202","c":"8039","t":"Accélérer les procédures."},{"id":"657-203","c":"8039","t":"Doubler les effectifs dans les juridictions correctionnelles."},{"id":"657-204","c":"8039","t":"Renforcer les greffes."},{"id":"657-205","c":"8039","t":"Dématérialiser l’ensemble du circuit judiciaire."},{"id":"657-206","c":"8039","t":"Abaisser la majorité pénale à 16 ans."},{"id":"657-207","c":"8039","t":"Inverser le principe de l’excuse de minorité dès 13 ans."},{"id":"657-208","c":"8039","t":"Créer un nouveau délit d’instrumentalisation de mineur."},{"id":"657-209","c":"8039","t":"Mettre en place des internats disciplinaires fermés."},{"id":"657-210","c":"8039","t":"Etendre la comparution immédiate dès 13 ans pour les cas graves."},{"id":"657-211","c":"8039","t":"Généraliser les travaux d’intérêt général dès le premier acte délictueux."},{"id":"657-212","c":"65","t":"Recruter davantage de fonctionnaires : magistrats, greffiers, agents de la protection judiciaire de la jeunesse."},{"id":"657-213","c":"65","t":"Rétablir pleinement les jurés populaires, supprimer les cours criminelles sans jurés et expérimenter les jurés dans les tribunaux correctionnels."},{"id":"657-214","c":"65","t":"Renforcer les droits de la défense, inscrire le droit à une défense dans la Constitution, renforcer la place de l’avocat."},{"id":"657-215","c":"65","t":"Garantir la gratuité des procédures les plus courantes (le divorce)."},{"id":"657-216","c":"65","t":"Confier au Parlement l’orientation de la politique pénale du pays par un débat annuel sur un texte avec un vote."},{"id":"657-217","c":"65","t":"Renforcer l’indépendance de la justice vis-à-vis de l’exécutif : interdire les instructions individuelles et les remontées d’information individuelles sauf lorsqu’elles appellent à une intervention directe de l’exécutif en matière d’ordre public (le terrorisme, par exemple)."},{"id":"657-218","c":"65","t":"Sécuriser le secret de l’instruction et de l’enquête, en renforçant les mécanismes de poursuite des auteurs et de leurs complices."},{"id":"657-219","c":"65","t":"En finir avec la surpopulation carcérale par la mise en place d’un mécanisme contraignant de régulation carcérale et assurer aux personnes détenues les moyens de se réinsérer dans notre société."},{"id":"657-220","c":"65","t":"Lutter contre la délinquance financière : doubler les effectifs des services qui luttent contre les infractions financières, supprimer le verrou de Bercy, donner plus de moyens humains aux brigades en charge de la délinquance financière, augmenter le nombre de juges d’instruction et supprimer la convention judiciaire d’intérêt public."},{"id":"657-221","c":"65","t":"Lutter contre l’impunité des agresseurs sexuels, la correctionnalisation des viols et intégrer la notion de consentement dans la définition pénale des infractions d’agression sexuelle et de viol."},{"id":"657-222","c":"65","t":"Punir les pollutions industrielles et appliquer strictement le principe pollueur-payeur."},{"id":"657-223","c":"65","t":"Abroger le code de justice pénale des mineurs de Dupond-Moretti pour instaurer un code de l’enfance combinant civil et pénal en concertation avec les professionnels."},{"id":"657-224","c":"65","t":"Construire des foyers supplémentaires qui permettent de séparer les enfants par tranches d’âge, préserver les fratries, préserver les jeunes victimes d’agressions sexuelles."},{"id":"657-225","c":"65","t":"Rendre obligatoire l’assistance d’un avocat pour chaque enfant placé."},{"id":"657-226","c":"65","t":"Interdire les placements de tous les mineurs dans des hôtels dans le cadre de l’Aide Sociale à l’Enfance (ASE) et rendre obligatoire leur prise en charge jusqu’à 25 ans par un contrat jeune majeur."},{"id":"657-227","c":"65","t":"Augmenter les effectifs de police spécialisés en lutte contre la cyberpédopornographie."},{"id":"657-228","c":"7805","t":"Mettre en place des peines courtes mais dissuasives dès la première infraction."},{"id":"657-229","c":"7805","t":"Mettre en place des peines planchers pour les infractions graves, par exemple lorsqu'elles portent atteinte à l'intégrité physique des personnes dépositaires de l'autorité publique."},{"id":"657-230","c":"7805","t":"Supprimer le juge d'application des peines pour que la peine décidée soit appliquée."},{"id":"657-231","c":"7805","t":"Développer le recrutement comme magistrats de juristes ayant exercé dans d'autres secteurs du droit."},{"id":"657-232","c":"7805","t":"Réviser la composition du Conseil Supérieur de la Magistrature (CSM) et instaurer un \"devoir de redevabilité\" à l'égard des victimes, pour renforcer la responsabilité des juges."},{"id":"657-233","c":"7805","t":"Renforcer l'autorité du ministre de la Justice, Garde des Sceaux, sur le parquet, notamment en instaurant la possibilité d'adresser des instructions individuelles aux procureurs."},{"id":"657-234","c":"7805","t":"Donner aux maires un pouvoir de sanction pénale afin qu'ils puissent réprimer les petites infractions."},{"id":"657-235","c":"7805","t":"Créer un principe de précaution pénale pour qu'à chaque plainte déposée liée aux enfants, une mesure de protection immédiate soit mise en place pour la victime potentielle."},{"id":"657-236","c":"7805","t":"Mettre en place l'imprescriptibilité pour les crimes sur mineurs."},{"id":"657-237","c":"7803","t":"Créer une « cour disciplinaire de la magistrature », soit un collège de citoyens désigné par tirage au sort, qui siégerait aux côtés de magistrats et de personnalités qualifiées."},{"id":"657-238","c":"7803","t":"Abolir la loi Belloubet."},{"id":"657-239","c":"7803","t":"Supprimer les JAP (juge d’application des peines)."},{"id":"657-240","c":"7803","t":"Instaurer des « peines planchers » pour les violences commises envers ceux qui détiennent l’autorité publique."},{"id":"657-241","c":"7803","t":"Permettre la castration chimique pour lutter contre la pédocriminalité."},{"id":"657-242","c":"8298","t":"Introduire des peines planchers pour tous les crimes et délits."},{"id":"657-243","c":"8298","t":"Appliquer les condamnations en mettant fin aux aménagements de peine."},{"id":"657-244","c":"8298","t":"Rétablir une peine de perpétuité réelle non-compressible."},{"id":"657-245","c":"8298","t":"Instauration de la « défense-excusable », amélioration du code de la légitime-défense."},{"id":"657-246","c":"8298","t":"Recruter davantage de magistrats et élargir leur recrutement aux professionnels de la sécurité publique (policiers, gendarmes) et du droit (avocats)."},{"id":"657-247","c":"8298","t":"Déchoir de la nationalité française les criminels binationaux et les délinquants récidivistes."},{"id":"657-248","c":"8298","t":"Expulser tous les squatteurs en moins de 72h, grâce au recours obligatoire à la force publique par les préfets."},{"id":"657-249","c":"8298","t":"Renforcer le pouvoir des maires contre les occupations illégales de terrains publics."},{"id":"657-250","c":"8298","t":"Suspendre les aides sociales aux délinquants."},{"id":"657-251","c":"8298","t":"Simplifier le code de procédure pénale."},{"id":"657-252","c":"8298","t":"Voter une grande loi de programmation de la Justice et de la Sécurité sur 5 ans."},{"id":"657-253","c":"8298","t":"Construire 10 000 places de prison supplémentaires en simplifiant le processus administratif."}]},{"id":"715","name":"Lutte contre le narcotrafic","ideas":[{"id":"715-254","c":"7805","t":"Créer un \"état d'urgence narco\" avec des moyens juridiques d'exception, limités dans le temps et dans l'espace, comme l'utilisation ciblée de la reconnaissance faciale."},{"id":"715-255","c":"7805","t":"Constituer une \"fiche S financière\" soit un profil bancaire spécifique pour les personnes condamnées pour narcotrafic."},{"id":"715-256","c":"7805","t":"Lever l'excuse de minorité pour les faits en lien avec le narcotrafic et créer la comparution immédiate des mineurs pour ces infractions."},{"id":"715-257","c":"7805","t":"Créer des établissements de réinsertion et de soin pour les mineurs condamnés pour narcotrafic."},{"id":"715-258","c":"7805","t":"Aligner le régime de l'application des peines des grands narcotrafiquants sur celui des terroristes."},{"id":"715-259","c":"7805","t":"Mobiliser la DGSI sur le narcotrafic et mener une grande réforme du renseignement économique et financier pour mieux tracer les fonds et saisir les avoirs."},{"id":"715-260","c":"7805","t":"Mettre en place un grand plan anticorruption des fonctionnaires : criblage systématique de toutes les fonctions sensibles (greffiers, agents fiscaux, préfectures) et réforme des habilitations."},{"id":"715-261","c":"7805","t":"Informer systématiquement les employeurs publics lorsqu’une personne chargée de mission de service public est poursuivie pour usage de stupéfiant."},{"id":"715-262","c":"7805","t":"Instaurer une \"tolérance zéro\" avec les consommateurs, par la mise en place d'opérations “place nette” dans les boîtes de nuit et festivals, le recouvrement forcé des amendes, y compris sur les prestations sociales."},{"id":"715-263","c":"7805","t":"Instaurer une liste noire des pays européens non-coopératifs en matière de narcotrafic, pour une \"diplomatie narco\"."},{"id":"715-264","c":"7803","t":"Instaurer un « état d’urgence anti-trafics » dans les quartiers les plus touchés par le narcotrafic."},{"id":"715-265","c":"7803","t":"Boucler 24h/24 les quartiers gangrenés par le trafic de drogue, en contrôlant les entrées et sorties, avec la possibilité de mobiliser des véhicules blindés de la gendarmerie et de couper les télécommunications."},{"id":"715-266","c":"7803","t":"Durcir la réponse judiciaire, notamment en allongeant la durée de détention provisoire pour les narcotrafiquants."},{"id":"715-267","c":"7803","t":"Renforcer les sanctions contre les mineurs impliqués dans les trafics, avec de courtes peines dès les premiers délits."},{"id":"715-268","c":"7803","t":"Frapper financièrement les narcotrafiquants, en renforçant les outils administratifs permettant de saisir ou neutraliser leurs ressources et leur patrimoine."},{"id":"715-269","c":"7803","t":"Réformer la Constitution afin de permettre la mise en œuvre de ces mesures exceptionnelles."}]},{"id":"669","name":"Sécurité intérieure","ideas":[{"id":"669-270","c":"7804","t":"Permettre à un maire de s'opposer à un mariage avec une personne sous OQTF."},{"id":"669-271","c":"10536","t":"Recruter et former 10 000 policiers et gendarmes supplémentaires en 5 ans."},{"id":"669-272","c":"10536","t":"Fixer un objectif de 10 000 douaniers et policiers supplémentaires aux frontières en 5 ans."},{"id":"669-273","c":"10536","t":"Mettre en place un plan national de rénovation des commissariats et casernes."},{"id":"669-274","c":"10536","t":"Instaurer la présomption de légitime défense pour les forces de l'ordre."},{"id":"669-275","c":"10536","t":"Augmenter sensiblement le taux de recouvrement des amendes."},{"id":"669-276","c":"8254","t":"Mettre en place une présomption de légitime défense pour les policiers et gendarmes."},{"id":"669-277","c":"8254","t":"Créer 7000 postes de policiers et gendarmes."},{"id":"669-278","c":"8254","t":"Obligation pour les communes de plus de 10 000 habitants à se doter d'une police municipale."},{"id":"669-279","c":"8039","t":"Donner aux préfets les moyens d'agir réellement avec des marges d’actions locales sur les effectifs et les équipements."},{"id":"669-280","c":"8039","t":"Ramener les forces de sécurité sur le terrain (50 % de présence minimum, contre 37 % aujourd’hui)."},{"id":"669-281","c":"8039","t":"Réduire la bureaucratie policière."},{"id":"669-282","c":"8039","t":"Moderniser les outils (vidéoprotection, radios numériques, IA de prévention)."},{"id":"669-283","c":"8039","t":"Instaurer un audit public annuel de la performance sécuritaire, localement et à l'échelle nationale."},{"id":"669-284","c":"8039","t":"Permettre aux communes volontaires d’armer leur police municipale et de disposer d’outils réels : accès aux fichiers, possibilité de verbalisation renforcée, procédures d’amendes forfaitaires délictuelles."},{"id":"669-285","c":"8039","t":"Face au narcotrafic, mettre en place des cellules locales anti-stups sous autorité du préfet, confisquer de façon ciblée et visible, infiltrer au niveau numérique les réseaux sociaux, coopérer au niveau international."},{"id":"669-286","c":"8039","t":"Face à l’islamisme, désigner de façon claire l’ennemi idéologique, interdire les Frères musulmans, contrôler les écoles hors contrat, expulser les prêcheurs radicaux, interdire le voile à l’université, mettre en place une campagne républicaine de contre-discours."},{"id":"669-287","c":"65","t":"Faciliter les poursuites contre les entreprises ou associations en cas d’activités illicites ou de fraude fiscale permettant le financement du terrorisme, instaurer comme peine principale la déchéance des droits civiques des personnes physiques qui y participent, et réquisitionner les entreprises qui collaborent avec les agresseurs."},{"id":"669-288","c":"65","t":"Renforcer les moyens humains du renseignement en revenant sur la fusion de la direction de la surveillance du territoire (DST) et des renseignements généraux (RG)."},{"id":"669-289","c":"65","t":"Revenir sur toutes les dispositions qui ont instauré un état d’urgence permanent."},{"id":"669-290","c":"65","t":"Renforcer les moyens humains de la plateforme PHAROS en charge de la prévention et de la surveillance des violences sur Internet."},{"id":"669-291","c":"65","t":"Intégrer au service public certaines fonctions de sécurité aujourd’hui privées, comme le gardiennage des services publics."},{"id":"669-292","c":"65","t":"Porter à deux ans la formation des élèves gardiens de la paix, réviser son contenu, et réouvrir des écoles nationales pour les activités de police."},{"id":"669-293","c":"65","t":"Interdire les tasers, les grenades de désencerclement, les « lanceurs de balles de défense 40 » (Flash-Ball)."},{"id":"669-294","c":"65","t":"Interdire les techniques d’immobilisation létales : le plaquage ventral, le pliage ventral et la clé d’étranglement."},{"id":"669-295","c":"65","t":"Interdire la technique de la « nasse » en manifestation, sauf en cas de mise en danger pour les personnes."},{"id":"669-296","c":"65","t":"Rétablir le code de déontologie de la police de 1986."},{"id":"669-297","c":"65","t":"Abroger la loi Cazeneuve sur le refus d’obtempérer, dite « permis de tuer »."},{"id":"669-298","c":"65","t":"Créer une commission « Vérité et Justice » sur les violences policières."},{"id":"669-299","c":"65","t":"Supprimer l’Inspection générale de la Police nationale (IGPN) et l’Inspection générale de la Gendarmerie nationale (IGGN) et les remplacer par une autorité indépendante incluant des magistrats, des universitaires, des citoyens, rattachée au Défenseur des droits."},{"id":"669-300","c":"65","t":"Créer une garde nationale sous commandement civil, composée de la réserve de sécurité nationale, de la réserve de sécurité civile, de la réserve citoyenne et des jeunes en service citoyen obligatoire ayant souhaité intégrer l’une de ces réserves."},{"id":"669-301","c":"65","t":"Démanteler les BAC."},{"id":"669-302","c":"65","t":"Construire de nouveaux centres d’activités de police de proximité."},{"id":"669-303","c":"65","t":"Intégrer les effectifs de police municipale à la nouvelle police de proximité."},{"id":"669-304","c":"65","t":"Interdire dans la loi tout usage des technologies de reconnaissance faciale dans les espaces et établissements publics sur le territoire français, ainsi que leur expérimentation."},{"id":"669-305","c":"65","t":"Augmenter les effectifs en charge de la délinquance financière, du trafic d’êtres humains et du démantèlement des réseaux mafieux et doubler les effectifs de la police technique et scientifique."},{"id":"669-306","c":"7805","t":"Lutter contre le proxénétisme en ligne en faisant fermer tous les sites qui le laissent prospérer."},{"id":"669-307","c":"7803","t":"Utiliser les technologies modernes comme la reconnaissance faciale."},{"id":"669-308","c":"8298","t":"Accorder aux policiers et aux gendarmes une présomption de légitime défense en cas d’usage de leurs armes."},{"id":"669-309","c":"8298","t":"Généraliser progressivement l’armement obligatoire des polices municipales."}]},{"id":"595","name":"Outre-mer","ideas":[{"id":"595-310","c":"65","t":"Engager un plan pluriannuel d’investissement et de développement des services publics."},{"id":"595-311","c":"65","t":"Mettre en place un encadrement des prix et des marges sur les produits de première nécessité pour lutter contre la vie chère, les monopoles et les oligopoles privés."},{"id":"595-312","c":"65","t":"Mettre en œuvre un plan de rattrapage spécifique sur les infrastructures routières et ferroviaires, en particulier à La Réunion et en Guyane."},{"id":"595-313","c":"65","t":"Garantir l’accueil scolaire et la santé publique gratuite pour tous."},{"id":"595-314","c":"65","t":"Soutenir l’enseignement des langues et des cultures d’Outre-mer, et intégrer dans les programmes scolaires nationaux, en France hexagonale et Outre-mer, l’enseignement de l’histoire des Outre-mer."},{"id":"595-315","c":"65","t":"Garantir 50 % de recrutements locaux dans tous les corps de la fonction publique."}]}]},{"id":"623","name":"Social & Solidarité","subs":[{"id":"624","name":"Allocations & prestations sociales","ideas":[{"id":"624-316","c":"7804","t":"Durcir et réformer l’assurance chômage pour inciter le retour à l’emploi et diminuer l’inactivité."},{"id":"624-317","c":"7804","t":"Pour le budget 2028, faire une année blanche sur l’ensemble des prestations sociales, en épargnant toutefois les petites retraites."},{"id":"624-318","c":"10357","t":"Elargir la Sécurité sociale à de nouveaux droits, pour une sécurité sociale alimentaire qui garantisse l'accès à la qualité alimentaire."},{"id":"624-319","c":"7806","t":"Donner un véritable statut aux familles monoparentales, qui leur garantisse un accès prioritaire à la garde d'enfants, à la caution pour le logement, aux transports."},{"id":"624-320","c":"8413","t":"Donner un statut aux familles monoparentales et prendre les ressources à l'instant T pour attribuer les aides sociales."},{"id":"624-321","c":"65","t":"Augmenter le minimum vieillesse au niveau du seuil de pauvreté (environ 1100 euros)."},{"id":"624-322","c":"65","t":"Garantir l’individualisation des droits et proposer l’automatisation des prestations sociales."},{"id":"624-323","c":"65","t":"Lutter contre le non-recours aux droits sociaux et civiques par la simplification des démarches et la réouverture des accueils physiques dans les services publics."},{"id":"624-324","c":"65","t":"Interdire les pratiques de notation des allocataires de prestations sociales."},{"id":"624-325","c":"65","t":"Revenir sur les réformes Macron en abrogeant l’éligibilité et les méthodes de calcul du montant et de la durée de l’allocation pour indemniser les chômeurs grâce à une assurance calculée à partir du premier jour de travail."},{"id":"624-326","c":"65","t":"Abroger la loi France Travail et l’obligation de réaliser 15h d’activités hebdomadaires contre le revenu de remplacement (allocation-chômage, RSA, ASS…)."},{"id":"624-327","c":"65","t":"Élargir la médecine du travail aux chômeurs, avec visite obligatoire au-delà de six mois."},{"id":"624-328","c":"65","t":"Indemniser les chômeurs dès le premier jour de la fin de contrat."},{"id":"624-329","c":"65","t":"Supprimer l’obligation d’accepter une « offre raisonnable d’emploi »."},{"id":"624-330","c":"65","t":"Abroger la présomption de démission en cas d’abandon de poste et le principe de fin des allocations chômage pour les intérimaires et les CDD qui refusent un CDI."},{"id":"624-331","c":"65","t":"Garantir le maintien du revenu en cas de reconversion ou de formation."},{"id":"624-332","c":"65","t":"Donner à chaque salarié le droit à 36 heures de formation par an, librement utilisables dans le domaine de son choix."},{"id":"624-333","c":"65","t":"Intégrer les périodes de stages et d’apprentissage dans la sécurité sociale professionnelle (ancienneté, congés, formation)."},{"id":"624-334","c":"65","t":"Augmenter de 0,25 point par an durant le quinquennat le taux de cotisation vieillesse et soumettre à cotisation les dividendes, les revenus d’intéressement, de participation, d’épargne salariale, ainsi que les revenus financiers des entreprises."},{"id":"624-335","c":"65","t":"Revaloriser l’AAH au niveau du SMIC."},{"id":"624-336","c":"7805","t":"Créer une aide financière unique et universelle pour les familles, en fusionnant les dispositifs existants trop complexes et éparpillés."},{"id":"624-337","c":"7803","t":"Réduire l’assistance grâce au Compte social unique (CSU) : chaque adulte disposerait d’un CSU retraçant l’ensemble des aides perçues, quelle qu’en soit l’origine, et permettant de construire un revenu social de référence. Gain : 10 Md€ d’économies."},{"id":"624-338","c":"7803","t":"Instaurer un revenu familial (RF) mensuel de 240 € par enfant, dès le premier enfant, de la naissance à ses 18 ans, remplaçant 12 dispositifs d’aide et de soutien aux parents."},{"id":"624-339","c":"7803","t":"Conditionner le revenu familial à une résidence régulière en France et à l’exercice d’une activité professionnelle depuis au moins cinq ans. En permettre la suspension temporaire par décision de justice en cas de défaillance éducative."},{"id":"624-340","c":"7803","t":"Conserver les aides spécifiques pour les enfants de 0 à 3 ans (PAJE), les parents seuls (ASF), le logement (APL) ou le handicap (AEEH).\nEconomies : 600 à 800M€ à terme.\nEconomies : proposition qui réduit de 25Md€ les prestations."},{"id":"624-341","c":"7803","t":"Encourager financièrement les familles nombreuses avec un RF doublé pour le troisième enfant mineur à charge.\nEffort budgétaire : 1,5Md€."},{"id":"624-342","c":"7803","t":"Recentrer le logement social sur ceux qui travaillent et leurs familles.\nPermettre aux familles ayant des enfants mineurs à charge de déduire une partie des intérêts de leur emprunt immobilier de leur impôt sur le revenu (50 % des intérêts déduits pour un enfant, 75 % pour deux et 100 % à partir de trois enfants)."},{"id":"624-343","c":"7803","t":"Etendre le congé de naissance jusqu’aux six mois de l’enfant, ouvert à l’un des deux parents qui serait indemnisé à 70 % de sa rémunération antérieure (dans la limite du plafond de la Sécurité sociale).\nDépense de la mesure : 700M€."},{"id":"624-344","c":"7803","t":"Supprimer le forfait social pour encourager participation et intéressement."},{"id":"624-345","c":"8038","t":"Abroger les réformes de l’assurance chômage adoptées sous Emmanuel Macron."},{"id":"624-346","c":"8038","t":"Développer le financement des formations vers les métiers d’avenir."},{"id":"624-347","c":"8038","t":"Lancer un grand plan contre le chômage des jeunes."},{"id":"624-348","c":"8038","t":"Développer les incitations financières à l’emploi durable."},{"id":"624-349","c":"8038","t":"Créer une carte vitale professionnelle."},{"id":"624-350","c":"8038","t":"Créer une sécurité sociale climatique."},{"id":"624-351","c":"8038","t":"Abroger les dispositions de la réforme Borne."},{"id":"624-352","c":"8038","t":"Augmenter les minimums vieillesse."},{"id":"624-353","c":"8038","t":"Obliger les fonds de retraites à adopter des investissements responsables."},{"id":"624-354","c":"8038","t":"Indexer le montant des pensions."},{"id":"624-355","c":"8038","t":"Améliorer les petites retraites."},{"id":"624-356","c":"8038","t":"Unifier les droits familiaux et conjugaux."},{"id":"624-357","c":"8038","t":"Remplacer le RSA par une garantie d’autonomie qui respecte la dignité et les droits des personnes allocataires."},{"id":"624-358","c":"8038","t":"Lutter contre le non-recours aux prestations."},{"id":"624-359","c":"8038","t":"Plafonner les frais bancaires."},{"id":"624-360","c":"8038","t":"Revaloriser les APL de 10%."}]},{"id":"602","name":"Santé","ideas":[{"id":"602-361","c":"7806","t":"Mieux rémunérer les soignants."},{"id":"602-362","c":"7806","t":"Encourager l’exercice mixte (hôpital/ville), favoriser les structures de soins regroupés pour faciliter le travail en équipe, contrer la financiarisation du système de santé, en finir avec la tarification à l’acte à l’hôpital, proposer un financement global, territorial et pluriannuel, actualiser les actes remboursés pour éviter que les grands groupes se concentrent uniquement sur les soins les plus rentables."},{"id":"602-363","c":"7806","t":"Créer un fonds territorial de prévention, permettant de financer des actions concrètes de prévention adaptées aux besoins locaux."},{"id":"602-364","c":"7806","t":"Santé mentale des jeunes : instaurer un dépistage précoce des troubles psychiques et addictologiques."},{"id":"602-365","c":"7806","t":"Mettre en place une sécurité sociale qui fusionne tous les régimes."},{"id":"602-366","c":"7806","t":"Abroger la réforme Macron de l’assurance chômage."},{"id":"602-367","c":"7806","t":"Instaurer une indemnité d’aidant familial pour ceux qui réduisent ou arrêtent leur travail pour s’occuper des aînés."},{"id":"602-368","c":"7806","t":"Créer un statut spécifique de « crèche sous-contrat » pour avoir un meilleur contrôle."},{"id":"602-369","c":"7806","t":"Supprimer les MDPH en transférant leurs missions à la Sécurité sociale."},{"id":"602-370","c":"8413","t":"Créer une mutuelle publique obligatoire gérée par la Sécurité sociale (projet de \"Grande Sécu\")."},{"id":"602-371","c":"8254","t":"Réforme de la gouvernance hospitalière : la tutelle des hôpitaux sera de nouveau confiée aux préfets de région à travers les Directions régionales des affaires sanitaires et sociales : les ARS seront purement et simplement supprimées."},{"id":"602-372","c":"8254","t":"Recrutements massifs de personnels soignants pour combler les postes vacants et revaloriser leurs salaires. Au moins 10.000 places supplémentaires seront ouvertes dans les Instituts de Formation en Soins infirmiers (IFSI) et les centres de formation d’aides-soignants."},{"id":"602-373","c":"8254","t":"Fixer un plafond de 10% de postes administratifs dans les hôpitaux, ce qui dégagera des marges de manœuvre pour recruter davantage de personnel soignant."},{"id":"602-374","c":"8254","t":"Instaurer un moratoire sur la suppression des lits à l’hôpital public."},{"id":"602-375","c":"8254","t":"Organiser un partenariat entre les services d’urgence et des cabinets médicaux libéraux vers lesquels pourraient être réorientés les patients relevant de la médecine de ville et non des urgences."},{"id":"602-376","c":"8254","t":"Créer une filière distincte pour les personnes les plus âgées. Cette filière spécifique doit permettre de limiter l’attente aux urgences, d’améliorer la prise en charge et de mieux orienter le patient âgé."},{"id":"602-377","c":"8254","t":"Redéfinir le mode de financement de l’hôpital public en revenant à un budget sous forme de dotation globale, afin de garantir la qualité des soins."},{"id":"602-378","c":"8254","t":"Réduire le nombre de déserts médicaux grâce à des incitations financières fortes, celles existantes, inefficaces, étant supprimées."},{"id":"602-379","c":"8254","t":"Développer la télémédecine sous toutes ses formes : téléconsultation, télésoins, téléexpertise."},{"id":"602-380","c":"8039","t":"Conventionnement différencié : la Sécurité sociale rembourse mieux les actes dans les zones sous-dotées que dans les zones saturées."},{"id":"602-381","c":"8039","t":"Généralisation des maisons de santé pluridisciplinaires à l'échelle locale."},{"id":"602-382","c":"8039","t":"Rendre l'accès aux infirmiers, kinés, et pharmaciens direct pour désengorger les généralistes et fluidifier les parcours."},{"id":"602-383","c":"8039","t":"Supprimer les ARS, transférer les responsabilités aux préfets et aux élus, redonner aux maires la présidence des conseils d’administration des hôpitaux."},{"id":"602-384","c":"8039","t":"Fonder la revalorisation salariale sur les responsabilités et non sur les statuts, et assouplir les recrutements de contractuels avec une reconnaissance pleine des compétences paramédicales dans une logique de coopération."},{"id":"602-385","c":"8039","t":"Doubler le nombre d’étudiants en médecine d’ici 2030, supprimer Parcoursup, simplifier la LAS/PASS, autoriser l’exercice sous supervision dès la 5e année et ouvrir tous les lieux de stage, publics comme privés."},{"id":"602-386","c":"8039","t":"Créer un consortium pharmaceutique européen pour mutualiser la demande, garantir des prix et relocaliser les chaines de valeur."},{"id":"602-387","c":"8039","t":"Réinvestir dans la recherche publique en santé et créer des clusters français de biotechnologie et de médecine génomique."},{"id":"602-388","c":"8039","t":"Construire une réglementation agile et sécurisée pour l’innovation médicale : télésurveillance, IA diagnostique, robotique chirurgicale."},{"id":"602-389","c":"65","t":"Ajouter le droit de mourir dans la dignité (y compris avec assistance) et l’accès garanti à des soins palliatifs dans la Constitution."},{"id":"602-390","c":"65","t":"Soutenir l’inclusion du droit à l’IVG et à la contraception, et leur accès gratuit pour toutes les femmes, dans la Charte européenne des droits fondamentaux."},{"id":"602-391","c":"65","t":"Déjudiciariser le changement de sexe à l’état-civil en le rendant libre et gratuit devant un officier d’état civil, pour les mineurs, permettre cette modification avec l’accord d’un des parents, en considérant qu’il s’agit d’une démarche courante comme le renouvellement de la carte d’identité."},{"id":"602-392","c":"65","t":"Établir la filiation par reconnaissance comme principe par défaut, refuser la gestation pour autrui (GPA), faire prévaloir l’intérêt supérieur de l’enfant comme principe premier, en toute circonstance."},{"id":"602-393","c":"65","t":"Accroître les moyens dédiés à l’assistance médicale à la procréation (PMA) pour réduire les délais et ouvrir des centres dédiés en nombre suffisant, harmoniser les pratiques à l’échelle nationale pour la rendre réellement accessible aux personnes trans, assurer l’égalité des populations et améliorer les parcours de dons."},{"id":"602-394","c":"65","t":"Encadrer le prix des produits alimentaires de première nécessité et interdire la réduflation."},{"id":"602-395","c":"65","t":"Assurer la gratuité des protections périodiques pour toutes et tous, quel que soit l’âge."},{"id":"602-396","c":"65","t":"Instaurer le repas à un euro dans tous les sites de restauration des Centres régionaux des œuvres universitaires (CROUS)."},{"id":"602-397","c":"65","t":"Instaurer le « 100 % Sécu » en remboursant à 100 % les soins de santé prescrits et en intégrant les mutuelles dans la Sécurité sociale."},{"id":"602-398","c":"65","t":"Réouvrir progressivement des services d’urgences, de maternités et des EHPAD publics assurant un service de santé public de proximité à moins de trente minutes de chaque Français."},{"id":"602-399","c":"65","t":"Remplacer l’objectif national des dépenses d’assurance-maladie (ONDAM) par un objectif national des besoins d’assurance-maladie (ONBAM), financer les hôpitaux par une dotation globale, un prix de journée et une tarification à l’acte pour les seules activités techniques programmées."},{"id":"602-400","c":"65","t":"Abroger la hausse des franchises médicales de 2024."},{"id":"602-401","c":"65","t":"Engager un plan pluriannuel de recrutement des professionnels du soin et du médico-social, revaloriser les métiers, les salaires et la tarification de certains actes libéraux des infirmiers."},{"id":"602-402","c":"65","t":"Recrutement de médecins publics."},{"id":"602-403","c":"65","t":"Financer l’augmentation du nombre de places en faculté de médecine en partant des besoins et la création d’écoles normales de santé dans les territoires."},{"id":"602-404","c":"65","t":"Rétablir l’obligation de participation de l’ensemble des médecins à la permanence des soins dans chaque département."},{"id":"602-405","c":"65","t":"Mettre fin à l’épidémie de VIH en France par un grand plan national de dépistage et de traitement."},{"id":"602-406","c":"65","t":"Rouvrir des lits de psychiatrie publics."},{"id":"602-407","c":"65","t":"Augmenter le nombre de places en faculté de médecine dans la filière psy."},{"id":"602-408","c":"65","t":"Légaliser et encadrer par un monopole d’État la consommation, la production et la vente de cannabis à des fins récréatives dans des conditions pour lutter contre l’addiction."},{"id":"602-409","c":"65","t":"Créer un ministère de la Production alimentaire pour lutter contre « la malbouffe »."},{"id":"602-410","c":"7805","t":"Stabiliser les dépenses de santé en dépensant mieux et en misant notamment sur la prévention et les transformations technologiques."},{"id":"602-411","c":"8038","t":"Lutter contre les déserts alimentaires."},{"id":"602-412","c":"8038","t":"Développer et soutenir les expérimentations de caisses locales de Sécurité sociale de l’Alimentation."},{"id":"602-413","c":"8038","t":"Améliorer les conditions de travail à l’hôpital public."},{"id":"602-414","c":"8038","t":"Conditonner le remboursement public des soins dans les cliniques privées."},{"id":"602-415","c":"8038","t":"Changer la gouvernance de l’hôpital public."},{"id":"602-416","c":"8038","t":"Augmenter les moyens et revaloriser les métiers de la psychiatrie et de la pédopsychiatrie publique."},{"id":"602-417","c":"8038","t":"Réformer le financement des hôpitaux."},{"id":"602-418","c":"8038","t":"Garantir un remboursement total des soins essentiels."},{"id":"602-419","c":"8038","t":"Combler les postes manquants de professionnels du soin et du médico-social."},{"id":"602-420","c":"8038","t":"Garantir l’accès à l’Aide médicale d’État (AME)."},{"id":"602-421","c":"8038","t":"Mettre en place un plan d’urgence pour la santé scolaire."},{"id":"602-422","c":"8038","t":"Créer un service public de la dépendance."},{"id":"602-423","c":"8038","t":"Reconnaître les aidants familiaux."},{"id":"602-424","c":"8038","t":"Lancer un plan Grand âge."},{"id":"602-425","c":"8298","t":"Recruter 1 000 médecins salariés par l’État sur 5 ans dans les déserts médicaux."},{"id":"602-426","c":"8298","t":"Créer des services hospitaliers de proximité dans les déserts médicaux (services de maternité, chimiothérapie, dépistage et chirurgie-dentaire)."},{"id":"602-427","c":"8298","t":"Rétablir un système de garde obligatoire pour les médecins sur l’ensemble du territoire national."}]},{"id":"569","name":"Culture","ideas":[{"id":"569-428","c":"7806","t":"Lancer un Pacte d’Aménagement culturel du Territoire (PACT), co-construit avec les collectivités, les acteurs culturels et l’État, pour garantir une présence culturelle de proximité partout en France."},{"id":"569-429","c":"7806","t":"Supprimer la part individuelle du pass Culture au profit du financement d’artistes intervenant en milieu scolaire."},{"id":"569-430","c":"7806","t":"Construire une histoire commune de la colonisation et de la décolonisation."},{"id":"569-431","c":"7806","t":"Renforcer le statut des artistes-auteurs par une loi garantissant continuité de revenus et droits sociaux adaptés."},{"id":"569-432","c":"65","t":"Porter le budget consacré à l’art, la culture et la création à 1 % du PIB par an."},{"id":"569-433","c":"65","t":"Créer une association sportive dans tous les établissements scolaires du 1er degré pour rendre gratuite la pratique d’une activité sportive."},{"id":"569-434","c":"8455","t":"Créer un plan national « Salles des fêtes et maisons du peuple » d’un milliard d’euros par an pendant cinq ans, pour rénover les salles des fêtes et locaux associatifs, ouvrir davantage les bâtiments publics aux activités culturelles et associatives et créer de nouveaux équipements polyvalents dans les territoires qui en sont dépourvus."}]},{"id":"519","name":"Logement","ideas":[{"id":"519-435","c":"7804","t":"Lancer un plan de construction de logements (400 000 / an)."},{"id":"519-436","c":"7804","t":"Prioriser la construction des logements étudiants et Crous."},{"id":"519-437","c":"7804","t":"Reprendre les mesures de simplification contenues dans la loi Kasbarian sur le logement abordable."},{"id":"519-438","c":"7804","t":"Contre l’instabilité du dispositif MaPrimRénov’, favoriser des monogestes planifiés, à l’unisson de la Capeb."},{"id":"519-439","c":"7804","t":"Faire voter une une loi de programmation sur le logement pour inscrire cet enjeu dans le temps long."},{"id":"519-440","c":"10536","t":"Elargir les conditions d'accès du Pret à taux zéro : augmenter le plafond de 100 000 euros, augmenter la part du PTZ dans l'emprunt global."},{"id":"519-441","c":"10536","t":"Créer un Prêt Accession à la Propriété ( PAP) à taux d’intérêt préférentiel et de longue durée pour aider les classes moyennes à acheter leur premier logement."},{"id":"519-442","c":"10536","t":"Encourager la transmission des biens immobiliers en augmentant le plafond des donations exonérées de droits de 100 000 euros supplémentaires par enfant ou petit enfant et en réduisant de 15 à 10 ans le délai minimum entre deux donations."},{"id":"519-443","c":"10357","t":"Mettre en place un bouclier logement pour le parc privé pour permettre que personne ne puisse dépenser plus de 30 % de ses revenus pour se loger."},{"id":"519-444","c":"7806","t":"Créer un fonds national pour aider les collectivités à acquérir du foncier et y développer du logement abordable, inciter à la densification des zones périurbaines, accélérer la construction de logements sociaux en rehaussant les objectifs nationaux annuels, via des contrats territoriaux."},{"id":"519-445","c":"7806","t":"Développer les logements en Bail réel solidaire (BRS) pour en faire une offre de masse pour que les ménages accèdent à la propriété, le BRS permettant d’acheter un logement sans le terrain afin de réduire les prix."},{"id":"519-446","c":"7806","t":"Accélérer la rénovation énergétique pour éviter les passoires thermiques."},{"id":"519-447","c":"7806","t":"Abroger la loi Kasbarian."},{"id":"519-448","c":"7806","t":"Réguler et maîtriser davantage les meublés touristiques comme au Pays basque et en Suisse pour limiter les activités des plateformes telles que Airbnb."},{"id":"519-449","c":"8413","t":"Baisser la charge des dépenses de logement dans le budget des ménages."},{"id":"519-450","c":"8254","t":"Remplacer les subventions à la rénovation thermique des logements de MaPrimeRénov’ par un dispositif de prêts à taux zéro 100 % Rénov."},{"id":"519-451","c":"8254","t":"Durcir les sanctions contre les locataires qui ne paient pas leur loyer et accélérer les procédures d’expulsion en cas d’impayés."},{"id":"519-452","c":"8254","t":"Supprimer les interdictions de louer les logements mal notés (classes F et G) pour éviter une crise du logement et préserver les propriétaires."},{"id":"519-453","c":"8254","t":"Abrogation de la loi SRU."},{"id":"519-454","c":"8254","t":"Mise en place d'une préference nationale : les français seront favorisés pour l'accès au logement et aux APL."},{"id":"519-455","c":"8254","t":"Supprimer la norme \" ZAN\", zéro artificialisation nette."},{"id":"519-456","c":"8254","t":"Supprimer un très grand nombre de normes liées à la performance énergétique et environnementale inutiles et contraignantes. Le DPE, Diagnostic de performance énergétique sera conservé mais uniquement à titre indicatif."},{"id":"519-457","c":"8254","t":"Supprimer la règle dictée par la loi de Solidarité et renouvellement urbain, qui impose entre 20 % et 25 % de logements sociaux dans les communes en zone urbaine."},{"id":"519-458","c":"8254","t":"Mettre gratuitement à disposition des promoteurs privés une partie du foncier de l’Etat et des entreprises publiques, en échange de la production de logements. L’Etat ne redeviendrait propriétaire que des décennies plus tard."},{"id":"519-459","c":"8254","t":"Concentrer les aides au recrutement dans les métiers du logement et du BTP au-dessous de bac +3."},{"id":"519-460","c":"10767","t":"Mettre en place l'encadrement des loyers et l'encadrement du prix du foncier."},{"id":"519-461","c":"65","t":"Atteindre l’objectif de zéro sans-abri : augmentation significative des places d’accueil (estimées aujourd’hui à 203 000) et simplification des dispositifs."},{"id":"519-462","c":"65","t":"Interdire les expulsions locatives sans relogement public."},{"id":"519-463","c":"65","t":"Abroger la loi Kasbarian de criminalisation des locataires."},{"id":"519-464","c":"65","t":"Mettre en place une garantie universelle des loyers créant un filet de sécurité contre les impayés de loyers pour les locataires, comme pour les propriétaires."},{"id":"519-465","c":"65","t":"Construire 200 000 logements publics par an pendant cinq ans aux normes écologiques les plus ambitieuses (RE2020, bâtiments à énergie positive)."},{"id":"519-466","c":"65","t":"Encadrer les loyers partout sur le territoire et à la baisse dans les grandes villes."},{"id":"519-467","c":"65","t":"Rehausser le quota de logements sociaux dans les villes (loi SRU) à 30 %, dont 5 % consacrés aux résidences universitaires et foyers jeunes travailleurs, et aggraver les sanctions contre les communes hors la loi."},{"id":"519-468","c":"65","t":"Rendre la rénovation des logements « passoires thermiques » obligatoire avant toute mise en location."},{"id":"519-469","c":"65","t":"Rétablir les aides publiques pour les HLM et éviter les hausses de loyers à la relocation en logement social."},{"id":"519-470","c":"65","t":"Réquisitionner les logements vides et les remettre sur le marché."},{"id":"519-471","c":"65","t":"Lutter contre la spéculation sur le logement en limitant les locations de courte durée à 60 jours par an et supprimer la niche fiscale sur les meublés de tourisme."},{"id":"519-472","c":"65","t":"Limiter la concentration immobilière en instaurant un plafond de cinq logements transmissibles par héritage ; au-delà, les biens sont réquisitionnés par l’État et redistribués entre le parc social et des dispositifs d’accès à la propriété par des organismes de foncier solidaire."},{"id":"519-473","c":"65","t":"Financer réellement la rénovation énergétique dans le cadre d'une large planification écologique."},{"id":"519-474","c":"65","t":"Créer un service public du recyclage des matériaux pour créer un circuit de l’économie circulaire."},{"id":"519-475","c":"65","t":"Combler les besoins de main d'œuvre du secteur, évalué à 300 000 personnes du CAP jusqu’à la licence professionnel."},{"id":"519-476","c":"7805","t":"Permettre un prêt à taux zéro à chaque naissance pour faciliter le déménagement des familles qui s'agrandissent."},{"id":"519-477","c":"7803","t":"Réduire l’impôt sur le revenu des ménages qui achètent une résidence principale, grâce à la déduction d’une quote-part des intérêts d’emprunt : 50 % des intérêts annuels lorsque le foyer compte un enfant mineur, 75 % s’il en compte deux, 100 % s’il en compte 3 ou plus. La réduction d’impôt annuelle est plafonnée à 400 €, majorés de 400 € additionnels par enfant mineur à charge."},{"id":"519-478","c":"7803","t":"Encourager la transmission du patrimoine immobilier aux jeunes générations grâce à un choc de transmission limité à 3 ans : relèvement temporaire du plafond des dons familiaux exonérés à 150 000 € pour les bénéficiaires de moins de 30 ans, et à 100 000 € pour ceux de moins de 40 ans, applicable également aux donations et successions portant sur le patrimoine immobilier."},{"id":"519-479","c":"7803","t":"Construire 1 million de logements supplémentaires en cinq ans : 350 000 par le statut du bailleur privé, 450 000 avec la fin des interdictions DPE, 150 000 par la transformation de bureaux en logements, 150 000 avec les friches et la densification."},{"id":"519-480","c":"7803","t":"Garantir la tolérance zéro envers le squat."},{"id":"519-481","c":"7803","t":"Supprimer les interdictions de louer fondées sur le DPE."},{"id":"519-482","c":"7803","t":"En finir avec l’encadrement des loyers. Supprimer les dispositifs d’encadrement des loyers issus de la loi ELAN. Abroger les mécanismes de plafonnement prévus par la loi de 1989."},{"id":"519-483","c":"7803","t":"Supprimer les quotas imposés aux maires et adapter la loi SRU à la réalité du terrain (les quotas de 20 % et 25 % seront supprimés pour redonner aux maires la liberté de construire)."},{"id":"519-484","c":"7803","t":"Reverser une part de TVA aux maires bâtisseurs : 9 000 € de TVA reversés à la commune pour chaque logement neuf."},{"id":"519-485","c":"7803","t":"Diviser par deux les délais de construction avec une loi d’urgence."},{"id":"519-486","c":"7803","t":"Libérer la transformation des bâtiments (transformer rapidement les bureaux et logements vacants en logements)."},{"id":"519-487","c":"7803","t":"Renforcer le statut de bailleur privé. L’amortissement universel à 4 % par an générera 350 000 logements supplémentaires sur la durée du quinquennat.\nGain net fiscal estimé : +1,9Md€."},{"id":"519-488","c":"7803","t":"Rendre les intérêts d’emprunt déductibles (pour les familles : 50 % avec un enfant, 75 % avec deux, 100 % à partir de trois)."},{"id":"519-489","c":"7803","t":"Refonder et développer le prêt à taux zéro (PTZ)."},{"id":"519-490","c":"7803","t":"Supprimer le ZAN."},{"id":"519-491","c":"7803","t":"Instaurer un moratoire normatif de 10 ans sur les règles applicables à la construction de logements."},{"id":"519-492","c":"7803","t":"Mettre en place le prêt social location-accession (PSLA) : dispositif d’accession progressive à la propriété."},{"id":"519-493","c":"7803","t":"Organiser un choc de transmission patrimoniale en faveur des jeunes générations. Le plafond du don familial (somme d’argent) sera très fortement relevé : 150 000 € exonérés pour un bénéficiaire de moins de 30 ans ; 100 000 € pour un bénéficiaire de moins de 40 ans."},{"id":"519-494","c":"7803","t":"Assurer un ordre de priorité clair et recentrer l’accès au logement social pour : ceux qui travaillent, les familles avec enfant."},{"id":"519-495","c":"7803","t":"Restituer le parc Action Logement aux salariés pour les loger à proximité de leur emploi."},{"id":"519-496","c":"7803","t":"Rétablir la rotation dans le parc social."},{"id":"519-497","c":"7803","t":"Supprimer progressivement l’exonération des organismes HLM sur cinq ans.\nEconomies : 350M€ (économies redistribuées aux bailleurs vertueux)."},{"id":"519-498","c":"7803","t":"Mettre fin au programme de rénovation urbaine en 2030.\nÉconomies : 100 à 150 M€."},{"id":"519-499","c":"7803","t":"Exclure de l’APL les étudiants dont les parents appartiennent aux deux derniers déciles de revenus.\nEconomies : 200 à 300 M€ / an."},{"id":"519-500","c":"7803","t":"Faciliter la mobilité résidentielle des familles, en imposant aux banques commerciales de permettre le transfert des prêts immobiliers d’un bien sur l’autre."}]},{"id":"550","name":"Transports","ideas":[{"id":"550-501","c":"7806","t":"Lancer un Plan Rail national en lien avec les régions : démultiplier les aides à SNCF Réseau afin de moderniser les infrastructures, développer les trains légers en zones rurales, relancer les Trains d’Équilibre du Territoire, ouvrir de nouvelles liaisons intercommunales et interrégionales, mettre en place un plan d’accessibilité des gares et trains."},{"id":"550-502","c":"7806","t":"Relancer les trains de nuit, accélérer les LGV et les liaisons prioritaires."},{"id":"550-503","c":"7806","t":"Mettre en place un Ticket climat : un titre de transport unique, à tarif fixe, abordable et valable à l’échelle nationale pour les transports du quotidien, d’abord réservé aux jeunes et aux publics précaires."},{"id":"550-504","c":"7806","t":"Développer les tramways, voies réservées aux bus, services express métropolitains en ville et périphérie, pistes cyclables et la tarification solidaire pour les jeunes et les ménages modestes."},{"id":"550-505","c":"7806","t":"Créer un service public de transport rural pour désenclaver les territoires."},{"id":"550-506","c":"7806","t":"Supprimer les exonérations de TVA et de taxe sur le kérosène, étendre l’interdiction des vols intérieurs avec alternative ferroviaire viable, taxation des plus gros pollueurs individuels (jets privés, yachts, SUV...)... Repenser le système autoroutier, faire un moratoire sur les grands projets autoroutiers et routiers d’État pour les réexaminer, affecter les recettes de péage à la mobilité durable et taxer les camions européens qui traversent nos territoires."},{"id":"550-507","c":"65","t":"Reconstruire le maillage de transports en commun et de services publics, notamment dans les départements ruraux, les quartiers prioritaires et les Outre-mer afin de garantir une distance maximale de 15 à 30 minutes entre tout lieu d’habitation et les services publics."},{"id":"550-508","c":"65","t":"Renationaliser la SNCF et refuser la mise en concurrence des lignes de transport."},{"id":"550-509","c":"65","t":"Refuser la suppression des lignes ferroviaires du quotidien et en réouvrir, augmenter le nombre de trains et garantir des tarifs accessibles, maintenir des guichets physiques dans les gares."},{"id":"550-510","c":"65","t":"Développer les transports publics à la demande hors des zones denses de transport public."},{"id":"550-511","c":"65","t":"Supprimer les lignes aériennes quand l’alternative en train est inférieure à quatre heures."},{"id":"550-512","c":"65","t":"Garantir l’accès aux réseaux dans les territoires peu dotés en transports collectifs par le soutien aux garages solidaires et une aide suffisante à la réparation dans le cadre du contrôle technique."},{"id":"550-513","c":"65","t":"Renationaliser les autoroutes, en revenant sur les hausses de prix passées, ainsi que les aéroports stratégiques."},{"id":"550-514","c":"7805","t":"Mettre en place un plan fret-ferroviaire pour limiter la circulation des camions."},{"id":"550-515","c":"8038","t":"Faire adopter une loi de programmation des infrastructures ferroviaires à 10 ans."},{"id":"550-516","c":"8038","t":"Plafonner le trafic aérien."},{"id":"550-517","c":"8038","t":"Doubler le kilométrage des voies cyclables en 3 ans."},{"id":"550-518","c":"8038","t":"Créer un ticket climat mensuel."},{"id":"550-519","c":"8038","t":"Accélérer l’électrification du parc automobile."},{"id":"550-520","c":"8038","t":"Créer un parc social de voitures bas carbone."},{"id":"550-521","c":"8298","t":"Restaurer la limitation de vitesse de 90km/h sur les routes nationales et départementales."},{"id":"550-522","c":"8298","t":"Désenclaver les bourgs des secteurs ruraux par une offre locale d’accès aux transports en commun routiers, notamment en mutualisant les équipements et services d’autres communes ou d’acteurs privés."},{"id":"550-523","c":"8298","t":"Refaire des lignes de trains « de proximité » la priorité budgétaire de la SNCF en identifiant les lignes à moderniser et en soutenant les politiques de désenclavement par le train."}]}]},{"id":"1128","name":"Retraites & Travail","subs":[{"id":"578","name":"Emploi & travail","ideas":[{"id":"578-524","c":"7804","t":"Défiscaliser les heures supplémentaires."},{"id":"578-525","c":"7804","t":"Réformer le 1er mai chômé pour permettre aux commerçants de travailler."},{"id":"578-526","c":"7804","t":"Réécrire le Code du travail : repartir de zéro avec les partenaires sociaux, les partis politiques et le gouvernement pour écrire un nouveau Code du travail qui soit une sorte de Constitution du travail, avec un petit nombre de grands principes, tout en laissant le reste aux accords de branche et accords d’entreprise."},{"id":"578-527","c":"7804","t":"Supprimer le plafond de 220 heures supplémentaires annuelles autorisées."},{"id":"578-528","c":"7804","t":"Plannifier la formation de 20 M de salariés sur 5 ans pour l’intelligence artificielle."},{"id":"578-529","c":"7804","t":"Faire baisser les charges salariales pour augmenter les salaires."},{"id":"578-530","c":"10357","t":"Limiter les écarts de salaires au sein des entreprises dans une proportion de 1 à 20."},{"id":"578-531","c":"10357","t":"Permettre un salaire garanti qui suit l'inflation au moins jusqu'au salaire médian."},{"id":"578-532","c":"10357","t":"Etablir le SMIC à 1 700 € net."},{"id":"578-533","c":"7806","t":"Organiser des conférences salariales dans toute la France pour renégocier avec les branches professionnelles les grilles de rémunération et les hausses de salaire."},{"id":"578-534","c":"7806","t":"Augmenter le SMIC à 1600€ net."},{"id":"578-535","c":"7806","t":"Soutenir les fonctionnaires, revaloriser durablement les rémunérations pour renforcer l’attractivité de la fonction publique, indexant leur point d’indice sur l’inflation et corrigeant les écarts de rémunérations entre ministères."},{"id":"578-536","c":"7806","t":"Soutenir les commerces de proximité en zones rurales en priorisant les projets à vocation sociale et écologique par des accompagnements ciblés et travailler à une « taxe Amazon » sur les grandes plateformes de e-commerce pour financer ce soutien."},{"id":"578-537","c":"7806","t":"Multiplier les centrales villageoises d’énergie renouvelable, épiceries coopératives, commerces de proximité solidaire… en déployant les Sociétés coopératives d’intérêt collectif."},{"id":"578-538","c":"7806","t":"Intégrer davantage les représentants des salariés dans les conseils d’administration des entreprises, dès 100 salariés (cf chèque syndical)."},{"id":"578-539","c":"7806","t":"Adopter une grande stratégie « Zéro mort au travail »."},{"id":"578-540","c":"7806","t":"Généraliser le dispositif Territoires Zéro Chômeur de longue durée, créer un CDI d’insertion harmonisé pour faciliter la transition vers l’emploi durable, et développer partout en France des Comités locaux pour l’Emploi réunissant habitants, associations et entreprises."},{"id":"578-541","c":"7806","t":"Créer un guichet unique territorial pour l’emploi et l’insertion, piloté par France Travail."},{"id":"578-542","c":"7806","t":"Booster l’emploi des jeunes : créer des guichets uniques jeunesse dans chaque territoire où les jeunes accèdent à un accompagnement gratuit et coordonné (emploi, logement, santé, droits)."},{"id":"578-543","c":"8413","t":"Augmenter le SMIC."},{"id":"578-544","c":"8413","t":"Produire plus en travaillant mieux, notamment en améliorant les conditions de travail et en employant plus les séniors."},{"id":"578-545","c":"8254","t":"Recenser les normes « toxiques » qu’il faut supprimer et celles qu’il faut simplifier par un travail « tricolore » (système de classification des normes)."},{"id":"578-546","c":"8254","t":"Mettre en place une vaste simplification administrative par ordonnances."},{"id":"578-547","c":"8254","t":"Créer un fonds souverain destiné à soutenir les PME."},{"id":"578-548","c":"10767","t":"Augmenter le SMIC."},{"id":"578-549","c":"10767","t":"Indexer les salaires sur l'inflation."},{"id":"578-550","c":"65","t":"Constituer des pôles publics dans les secteurs stratégiques : médicaments, transports et mobilité, banque, énergie, armement."},{"id":"578-551","c":"65","t":"Accorder aux comités d’entreprise un droit de veto suspensif sur les plans de licenciements et de nouveaux droits de contrôle sur les finances de leur entreprise."},{"id":"578-552","c":"65","t":"Donner plus de pouvoir aux salariés lors des procédures de redressement et de liquidation d’entreprise et instaurer le droit à un vote de défiance à l’égard des dirigeants d’entreprise ou des projets stratégiques."},{"id":"578-553","c":"65","t":"Augmenter la représentation des salariés dans les instances de décision des grandes entreprises à au moins un tiers et inclure d’autres parties prenantes comme les associations environnementales ou de consommateurs."},{"id":"578-554","c":"65","t":"Garantir les droits des représentants des personnels et des délégués syndicaux contre les licenciements abusifs des salariés protégés."},{"id":"578-555","c":"65","t":"Tout chômeur de longue durée pourra se voir proposer d’être embauché au moins au SMIC revalorisé dans un secteur d’urgence."},{"id":"578-556","c":"65","t":"Rétablir la durée légale hebdomadaire à 35h en majorant les heures supplémentaires, cotisations incluses, à 25% pour les 4 premières et 50% au-delà."},{"id":"578-557","c":"65","t":"Passer aux 32 heures hebdomadaires pour les métiers pénibles ou de nuit."},{"id":"578-558","c":"65","t":"Généraliser une sixième semaine de congés payés pour tous les salariés."},{"id":"578-559","c":"65","t":"Remettre en cause les autorisations de travail le dimanche."},{"id":"578-560","c":"65","t":"En finir avec la flexibilisation, l’annualisation contrainte, l’intensification et les horaires fractionnés."},{"id":"578-561","c":"65","t":"Instaurer un quota maximal de contrats précaires dans les entreprises : 10 % pour les PME, 5 % pour les grandes entreprises."},{"id":"578-562","c":"65","t":"Abroger les ordonnances Pénicaud et la loi El Khomri et rétablir le « principe de faveur »."},{"id":"578-563","c":"65","t":"Transposer dans le droit français la directive européenne sur la présomption de salariat empêchant les plateformes numériques (Uber, Deliveroo, etc.) d’avoir recours aux faux indépendants."},{"id":"578-564","c":"65","t":"Titulariser les précaires des trois fonctions publiques."},{"id":"578-565","c":"65","t":"Encadrer la sous-traitance en garantissant par la loi la responsabilité des donneurs d’ordre vis-à-vis de leurs sous-traitants et en la limitant à un seul niveau."},{"id":"578-566","c":"65","t":"Porter le SMIC à 1 600€ net et indexer les salaires sur l’inflation dans le privé et dans la fonction publique."},{"id":"578-567","c":"65","t":"Revaloriser la rémunération des apprentis et des alternants."},{"id":"578-568","c":"65","t":"Fixer un salaire maximal autorisé pour limiter l’écart de 1 à 20 entre le salaire le plus bas et le salaire le plus haut dans une entreprise."},{"id":"578-569","c":"65","t":"Plafonner les versements de dividendes aux actionnaires en limitant la part des bénéfices qui leur est distribuée à la part versée aux employés."},{"id":"578-570","c":"65","t":"Supprimer les stock-options et le versement d’actions gratuites."},{"id":"578-571","c":"65","t":"Augmenter la représentation des salariés dans les conseils d’administration."},{"id":"578-572","c":"65","t":"Porter un objectif de « zéro mort au travail »."},{"id":"578-573","c":"7805","t":"Rééquilibrer le financement du modèle social pour qu'il ne repose plus uniquement sur le travail et augmenter le salaire net des actifs."},{"id":"578-574","c":"7805","t":"Créer un temps partiel parental, à 80 % rémunéré 100 % pendant 2 mois pour faciliter la reprise des parents après les congés parentaux."},{"id":"578-575","c":"7803","t":"Travailler plus et gagner plus grâce au seuil « zéro cotisation » : beaucoup d’entrerpises hésitent à proposer des heures supplémentaires car leur coût marginal demeure trop élevé."},{"id":"578-576","c":"7803","t":"Encourager la reprise d’activité avec le Revenu d’incitation à l’activité (RIA) : ce revenu remplacerait 3 dispositifs (RSA, prime d’acitivité et allocation de solidarité spécifique) pour que chaque heure travaillée apporte un bénéfice visible.\nGain : 2 Md€ d’économies."},{"id":"578-577","c":"7803","t":"Libérer le travail des seniors qui ont tous leurs trimestres : seuls 36 % des 60-64 ans sont en emploi, contre 60 % en Europe en moyenne, ce qui s’explique par un coût du travail dissuasif en fin de carrière."},{"id":"578-578","c":"7803","t":"Réformer l’assurance chômage pour accélérer le retour à l’emploi : publier le décret Attal avec des mesures complémentaires.\nGain : 12,5 à 15,7 Mds d’€ d’économies."},{"id":"578-579","c":"7803","t":"Renforcer le pilier de la retraite par capitalisation pour compléter le système par répartition."},{"id":"578-580","c":"7803","t":"Mettre en place, au-delà de la 35ᵉ heure travaillée, des heures supplémentaires qui ne donnent lieu ni à cotisations sociales, ni patronales, ni salariales."},{"id":"578-581","c":"14","t":"Nationaliser TotalEnergies."},{"id":"578-582","c":"10360","t":"Augmenter les bas salaires et réunir immédiatement après l'élection présidentielle une conférence salariale avec des négociations par branche pour aider les petites entreprises à supporter cette augmentation."},{"id":"578-583","c":"10360","t":"Remettre à plat l'utilisation des 150 Md€ d'aides aux entreprises, arrêter de les distribuer aux entreprises qui distribuent des dividendes, et les utiliser pour aider les petites et moyennes entreprises à augmenter le SMIC."},{"id":"578-584","c":"10360","t":"Supprimer le crédit impôt recherche pour les entreprises qui distribuent des dividendes."},{"id":"578-585","c":"10360","t":"Bloquer les prix des produits de première nécessité, avec un panier type de consommation, pour conserver un niveau de qualité alimentaire égal pour tous."},{"id":"578-586","c":"8038","t":"Garantir l’engagement réel des entreprises en conditionnant les aides publiques à des critères environnementaux et sociaux."},{"id":"578-587","c":"8038","t":"Rehausser les soutiens à l’Économie Sociale et Solidaire (ESS)."},{"id":"578-588","c":"8038","t":"Créer un prêt à taux zéro pour les projets de décarbonation des PME et ETI."},{"id":"578-589","c":"8038","t":"Instaurer un droit effectif à la participation des travailleurs dans les entreprises de plus de 250 salariés."},{"id":"578-590","c":"8038","t":"Soutenir le droit syndical et les moyens d’auto-organisation des salariés."},{"id":"578-591","c":"8038","t":"Encadrer la sous-traitance."},{"id":"578-592","c":"8038","t":"Augmenter les fonds dédiés à la formation professionnelle et les affecter à l’ensemble des salariés."},{"id":"578-593","c":"8038","t":"Lancer un plan national « Santé mentale et travail soutenable »."},{"id":"578-594","c":"8038","t":"Instaurer un droit social numérique."},{"id":"578-595","c":"8038","t":"Protéger les travailleurs face aux températures extrêmes."},{"id":"578-596","c":"8038","t":"Instaurer une garantie d’emploi pour les chômeurs longue durée."},{"id":"578-597","c":"8038","t":"Limiter les écarts de salaire de 1 à 20 dans les entreprises."},{"id":"578-598","c":"8038","t":"Augmenter le SMIC à 1600€ en deux ans."},{"id":"578-599","c":"8038","t":"Indexer le point d’indice des fonctionnaires sur l’inflation."},{"id":"578-600","c":"8038","t":"Pénaliser les agroindustriels qui commercialisent des produits nocifs pour la santé."},{"id":"578-601","c":"8298","t":"Revenir pleinement au principe « Travailler plus pour gagner plus »."},{"id":"578-602","c":"8298","t":"Maintenir l’exonération de cotisations patronales et salariales à hauteur du SMIC pendant deux ans."},{"id":"578-603","c":"8298","t":"Rémunérer les salariés qui participent à la création de richesse de leur entreprise en simplifiant et défiscalisant la prime de participation des salariés."},{"id":"578-604","c":"8298","t":"Permettre le déblocage immédiat de la prime de participation sans aucun impôt sur le revenu et sans aucune condition pour le salarié."},{"id":"578-605","c":"8298","t":"Mettre fin au dumping social provoqué par l’actuelle directive européenne sur les travailleurs détachés."},{"id":"578-606","c":"8298","t":"Favoriser les embauches en exonérant de cotisations patronales toute petite entreprise de moins de 11 salariés pour deux embauches en CDI, pendant 2 ans."},{"id":"578-607","c":"8298","t":"Favoriser la mobilité des chercheurs d’emploi sur le territoire en versant directement la moitié des droits au chômage en cas de déménagement pour prendre un nouvel emploi."},{"id":"578-608","c":"8298","t":"Favoriser le pouvoir d’achat des apprentis en augmentant le niveau d’exonération des cotisations salariales pour l’apprentissage de 79 % à 100 % du SMIC."},{"id":"578-609","c":"8298","t":"Favoriser l’embauche des apprentis en CDI en réinstaurant et maintenant l’exonération de cotisations patronales et salariales à hauteur du SMIC pendant 2 ans en cas d’embauche de l’apprenti par l’entreprise d’accueil."},{"id":"578-610","c":"8298","t":"Relever le seuil de 50 à 250 salariés pour l’obligation de consultation du Comité social et économique (CSE), tout en maintenant les œuvres sociales et culturelles pour les entreprises d’au moins 50 salariés."},{"id":"578-611","c":"8298","t":"Baisser fortement les impôts de production à hauteur de 30 milliards d’euros supplémentaires par an, en supprimant en priorité la Contribution Sociale de Solidarité des Sociétés (C3S), la Cotisation sur la Valeur Ajoutée des Entreprises (CVAE) et la Cotisation Foncière des Entreprises (CFE)."},{"id":"578-612","c":"8298","t":"Créer des zones franches industrielles ouvrant droit à une exonération d’impôts de production et d’impôts sur les sociétés pendant 5 ans."},{"id":"578-613","c":"8298","t":"Baisser le taux d’impôt sur les sociétés à 15 % pour les petites et moyennes entreprises, artisans, commerçants et agriculteurs jusqu’à 300 000 euros de bénéfices."},{"id":"578-614","c":"8298","t":"Supprimer les droits de donation et de succession pour la transmission des entreprises familiales."}]},{"id":"1130","name":"Système de retraite","ideas":[{"id":"1130-615","c":"7804","t":"Changer de système de retraite : supprimer l’âge légal de départ, maintenir la durée de cotisation. Mettre en place une décote pour ceux qui partent plus tôt et une surcote pour ceux qui partent plus tard."},{"id":"1130-616","c":"7804","t":"Introduire une part de capitalisation dans ce nouveau système de retraite, grâce à une dotation en capital gérée par un fonds souverain, abondé automatiquement à hauteur de 1 000 € par l’État à la naissance de chaque enfant. Il pourrait être abondé par la famille jusqu’à ses 18 ans, via un abattement fiscal. Les fonds de pensions pourront alors permettre de financer nos start-ups, entreprises et PME."},{"id":"1130-617","c":"7804","t":"Créer un système de retraite universel qui garantisse les mêmes règles pour tous, c'est à dire aligner les régimes des salariés (privé), des fonctionnaires (public) et des indépendants."},{"id":"1130-618","c":"10536","t":"Fournir un \" minimum retraite \" de 10 000 euros à chaque nouveau né français, qui sera gelé jusqu'à 60 ans."},{"id":"1130-619","c":"10357","t":"Abroger la réforme des retraites dite réforme Borne."},{"id":"1130-620","c":"10357","t":"Construire une réforme des retraites qui instaure que les personnes exerçant des métiers à fortes pénibilités puissent partir à la retraite avec moins d'annuités."},{"id":"1130-621","c":"7806","t":"Abroger la réforme Macron de 2023."},{"id":"1130-622","c":"7806","t":"Passer à un système qui prend en compte la durée de cotisation."},{"id":"1130-623","c":"7806","t":"Imaginer une réforme des retraites qui mette la pénibilité des métiers au cœur."},{"id":"1130-624","c":"8254","t":"Permettre un départ à 60 ans pour ceux qui ont commencé à travailler avant 20 ans."},{"id":"1130-625","c":"8254","t":"Instaurer une part de capitalisation « volontaire » dans le système des retraites, dans le cadre d’un \"fonds d’investissement dans l’avenir de la France\"."},{"id":"1130-626","c":"8039","t":"Entreprendre une réforme structurelle comprenant une part de capitalisation pour les retraites, tout en conservant un premier étage par répartition qui garantisse un socle minimum de pension autour de 1 200 € mensuels."},{"id":"1130-627","c":"65","t":"Abroger la réforme des retraites à 64 ans et rétablir le droit à la retraite à 60 ans avec 40 annuités de cotisation."},{"id":"1130-628","c":"65","t":"Augmenter les petites retraites jusqu’au SMIC revalorisé à 1 600 €."},{"id":"1130-629","c":"65","t":"Indexer le montant des retraites sur les salaires."},{"id":"1130-630","c":"65","t":"Interdire les parachutes dorés et les retraites chapeaux."},{"id":"1130-631","c":"65","t":"Réformer le système des retraites agricoles."},{"id":"1130-632","c":"7805","t":"Introduire une part de capitalisation dans notre système de retraite :\n• créer un fonds de capitalisation collective obligatoire (étendre celui qui existe déjà pour les fonctionnaires aux salariés), financé par les excédents de l'Agirc-Arrco qui seront dégagés par la réforme,\n• instituer un plan d'épargne retraite individuel obligatoire, abondé dès le premier contrat de travail de 500 € de la part de l'Etat.\nL'objectif est que les jeunes qui entrent aujourd'hui sur le marché du travail puissent bénéficier de 20 % à 25 % de capitalisation sur sa pension."},{"id":"1130-633","c":"7805","t":"Confier la gestion du régime à l'équilibre aux partenaires sociaux."},{"id":"1130-634","c":"7805","t":"Porter, d'ici 10 ans au maximum, l'âge légal de départ à la retraite à 65 ans et la durée de cotisation à 45 ans. Un Français sur trois ne sera pas soumis à l'âge légal de 65 ans et pourra bénéficier d'un départ anticipé en fonction de la pénibilité du métier exercé. Il reviendra aux partenaires sociaux de déterminer qui sera concerné par ces départs anticipés."},{"id":"1130-635","c":"7803","t":"Permettre un départ à la retraite à 63 ans (âge minimal), à taux réduit : décote de 7 % par an ; instituer un départ à la retraite à 65 ans à taux plein. Objectif : 40 Md€ d'économies en 5 ans."},{"id":"1130-636","c":"7803","t":"Lier par une équation proportionnelle l'âge de la retraite et l'espérance de vie."},{"id":"1130-637","c":"7803","t":"Mettre en place une part de retraite par capitalisation, financée par une cotisation de 1 % du revenu brut, complétée par d’autres abondements notamment volontaires. La cible est de 25 % de capitalisation pour ceux qui entreront sur le marché du travail en 2027 avec une montée en puissance progressive."},{"id":"1130-638","c":"7803","t":"Engager avec les partenaires sociaux une discussion afin de déterminer l'âge de départ à la retraite pour les métiers aux plus fortes pénibilités et les carrières longues."},{"id":"1130-639","c":"7803","t":"Supprimer les cotisations retraite et chômage pour les personnes (et leurs employeurs) ayant atteint toutes leurs annuités à 62 ans, pour augmenter de 15 % leur salaire net."},{"id":"1130-640","c":"8298","t":"Revaloriser jusqu’à 600 € / an les petites retraites inférieures à 1300 € / mois par l’exonération de CSG et CRDS."}]},{"id":"653","name":"Industrie & relocalisation","ideas":[{"id":"653-641","c":"7806","t":"Soutenir la reprise de certaines entreprises par les salariés, sous forme de Sociétés Coopératives et Participatives."},{"id":"653-642","c":"7806","t":"Création de fonds régionaux conséquents pour permettre aux régions d’entrer au capital d’entreprises clés."},{"id":"653-643","c":"7806","t":"Renforcer nos outils de défense commerciale pour activer des clauses de protection quand un secteur est menacé, sanctionner le dumping, surveiller de près les investissements étrangers dans les secteurs stratégiques, imposer aux produits importés les mêmes normes que celles exigées chez nous (mesures miroirs)."},{"id":"653-644","c":"7806","t":"Défendre le « Fabriqué en France », en orientant la commande publique française avec des critères durables et souverains et un indice d’achat local."},{"id":"653-645","c":"7806","t":"Relocaliser la production de batteries et accélérer l’innovation sur toute la chaine - batteries solides, seconde vie, recyclage."},{"id":"653-646","c":"8254","t":"Permettre la priorité nationale de la commande publique."},{"id":"653-647","c":"65","t":"Poursuivre les atteintes au patrimoine industriel français faisant partie des « intérêts fondamentaux de la Nation » comme le prévoit le Code pénal."},{"id":"653-648","c":"65","t":"Relocaliser les productions essentielles à la vie du pays."},{"id":"653-649","c":"65","t":"Adopter des mesures antidumping d’urgence sur les industries stratégiques : sidérurgie, automobile, pharmaceutique…"},{"id":"653-650","c":"65","t":"Réviser le Code des marchés publics pour favoriser les entreprises sociales et solidaires, écologiques et locales."},{"id":"653-651","c":"7803","t":"Refonder le code du travail sur 50 principes, rendre le reste à la négociation collective."},{"id":"653-652","c":"7803","t":"Réduire franchement les prélèvements obligatoires."},{"id":"653-653","c":"7803","t":"Garantir un prix de l’électricité durablement compétitif pour l’industrie française."},{"id":"653-654","c":"7803","t":"Investir dans l’outil de production pour restaurer la souveraineté française."},{"id":"653-655","c":"7803","t":"Remettre l’outil de formation au service de l’emploi et de l’économie."},{"id":"653-656","c":"7803","t":"Libérer la transmission du capital productif."},{"id":"653-657","c":"7803","t":"Encourager l’épargne à soutenir le financement de l’économie."},{"id":"653-658","c":"7803","t":"Alléger la production par un choc fiscal de 40 Md€ financé par les économies."},{"id":"653-659","c":"8298","t":"Faire converger la formation et les besoins des entreprises en rattachant les lycées professionnels au ministère de l’Industrie."},{"id":"653-660","c":"8298","t":"Exiger le remboursement intégral des aides publiques reçues par les entreprises qui délocalisent."},{"id":"653-661","c":"8298","t":"Créer un ministère de l’Industrie regroupant Industrie, Commerce extérieur, Énergie et Transports pour permettre la réindustrialisation."},{"id":"653-662","c":"8298","t":"Créer un comité dédié chargé de contrôler tous les investissements étrangers."}]}]},{"id":"481","name":"Environnement","subs":[{"id":"579","name":"Energie","ideas":[{"id":"579-663","c":"7804","t":"Doubler la part du fonds chaleur, NDLR dédiée au financement de la géoénergie de 80 M€ à 160 M€."},{"id":"579-664","c":"10357","t":"Mettre en œuvre des aides ciblées pour lutter contre la hausse des prix des carburants."},{"id":"579-665","c":"10357","t":"Plafonner les marges de TotalEnergies."},{"id":"579-666","c":"7806","t":"Lancer un grand plan d’investissement pluriannuel dans toutes les énergies renouvelables."},{"id":"579-667","c":"7806","t":"Conforter le rôle du nucléaire."},{"id":"579-668","c":"7806","t":"Investir dans le réseau électrique et de nouvelles capacités de stockage pour mieux relier les sites de production d’énergies renouvelables et les lieux de consommation."},{"id":"579-669","c":"7806","t":"Faire baisser les prix de l’électricité : fixer une partie de la facture des ménages, entreprises, industriels et collectivités sur le coût de production de notre électricité nucléaire."},{"id":"579-670","c":"7806","t":"Annuler la hausse de taxe sur l’électricité imposée en 2024."},{"id":"579-671","c":"7806","t":"Devenir souverain par la sobriété, le réusage, la réparation et le recyclage, tout en ouvrant, dans le respect des normes strictes, de nouvelles mines et raffineries de métaux critiques."},{"id":"579-672","c":"7806","t":"Soutenir la filière française de la petite voiture électrique, légère, abordable et réparable, accessible aux classes moyennes et populaires."},{"id":"579-673","c":"7806","t":"Relancer et simplifier MaPrimeRénov'."},{"id":"579-674","c":"7806","t":"Interdire l'importation de gaz russe pour que la France cesse d'être le premier importateur européen de gaz naturel liquéfié russe."},{"id":"579-675","c":"7806","t":"Investir dans l'électrification : proposer une mesure de leasing social pour permettre à 100 000 auxiliaires de vie d'avoir accès à une voiture électrique pour 100 euros par mois, en soutenant la filière européenne de la voiture électrique. Coût : moins de 1 Md€ /an."},{"id":"579-676","c":"8254","t":"Sortir du marché européen de l’électricité."},{"id":"579-677","c":"8254","t":"Retourner à un prix national de l’électricité."},{"id":"579-678","c":"8254","t":"Baisser la TVA sur l’énergie et les carburants de 20 % à 5,5 %."},{"id":"579-679","c":"8254","t":"Mettre en place un « grand plan nucléaire » et le démantèlement progressif des parcs éoliens existants lorsqu’ils arrivent en fin de vie."},{"id":"579-680","c":"10767","t":"Guérir de notre addiction au pétrole et aux hydrocarbures : investir de manière très conséquente dans l'électrification."},{"id":"579-681","c":"10767","t":"Plafonner les marges des distributeurs et des raffineurs pour lutter contre l'explosion du prix des carburants."},{"id":"579-682","c":"10767","t":"Subventionner le rétrofit électrique : changer les moteurs thermiques en moteurs électriques."},{"id":"579-683","c":"10767","t":"Développer le leasing social pour faciliter l'accès aux voitures électriques."},{"id":"579-684","c":"10767","t":"Sortir de la tarification européenne de l'électricité, selon laquelle le prix de l'électricité est indexé sur le celui du gaz."},{"id":"579-685","c":"65","t":"Planifier le passage à 100 % d’énergies renouvelables."},{"id":"579-686","c":"65","t":"Développer les énergies marines renouvelables dans le cadre du plan de transition énergétique et d’une maitrise publique des installations et réseaux, tout en veillant à concilier les usages en mer."},{"id":"579-687","c":"7805","t":"Ouvrir un accès préférentiel à notre énergie décarbonée pour les acteurs nationaux et européens, avec des règles de raccordement inspirées des Al Growth Zones britanniques."},{"id":"579-688","c":"7803","t":"Consolider le parc nucléaire par la construction de 6 nouveaux réacteurs APR2 sans dérapage et 8 réacteurs supplémentaires dès le début du mandat.\nCoût de l’électricité produite : 2 fois moins cher que le solaire subventionné, 2,5 fois moins cher que l’éolien en mer."},{"id":"579-689","c":"7803","t":"Relancer l’hydroélectricité française tout en stoppant les subventions à l’éolien et au solaire en métropole."},{"id":"579-690","c":"7803","t":"Faire baisser la facture des Français grâce au nucléaire qu’ils ont payé (par leurs impôts) : objectif -5 % à -15 % sur la facture dès 2030."},{"id":"579-691","c":"7803","t":"Supprimer les taxes pour faire baisser la facture : suppression des CEE avec effet immédiat ce qui permet -5 % sur la facture."},{"id":"579-692","c":"7803","t":"Arrêter de pénaliser le chauffage électrique dans le DPE : 750 000 logements pourront être remis en location."},{"id":"579-693","c":"7803","t":"Reprendre la main sur l’uranium, les batteries et la sécurité du réseau (en stockant 5 ans d’uranium, en lançant avec nos partenaires européens un grand programme industriel pour reprendre la main sur les batteries et en protégeant notre réseau électrique contre le piratage)."},{"id":"579-694","c":"7803","t":"Inscrire le parc nucléaire dans une trajectoire « 80 ans »."},{"id":"579-695","c":"7803","t":"Confirmer les nouveaux EPR2 en veillant à la tenue des coûts et des délais."},{"id":"579-696","c":"7803","t":"Lever immédiatement, et à coût budgétaire nul, les freins à l’électrification."},{"id":"579-697","c":"7803","t":"Bloquer l’European grid package et réaffirmer la souveraineté française."},{"id":"579-698","c":"7803","t":"Abroger le volet électricité de la PPE 3, déclarer infructueux les appels d’offres non encore attribués en matière de photovoltaïque et d’éolien en mer, et ne plus en lancer tant que la demande n’augmente pas nettement."},{"id":"579-699","c":"7803","t":"Supprimer l’ensemble des avantages fiscaux et tarifaires associés aux nouvelles installations photovoltaïques."},{"id":"579-700","c":"7803","t":"Sortir l’électricité du périmètre des CEE et concentrer l’effort sur les opérations de sortie des fossiles les plus efficaces à l’euro investi.\nEconomies : baisse directe des factures d’électricité."},{"id":"579-701","c":"7803","t":"Franchir la frontière de la 4e génération nucléaire : les réacteurs à neutrons rapides."},{"id":"579-702","c":"7803","t":"Faire respecter le principe de subsidiarité et la souveraineté française sur son mix énergétique au niveau européen."},{"id":"579-703","c":"8298","t":"Supprimer l’objectif de réduire à 50 % la part du nucléaire dans notre mix électrique en 2035 et allonger la durée de vie du parc existant à 60 ans au moins."},{"id":"579-704","c":"8298","t":"Stopper la fermeture prévue des 12 réacteurs nucléaires annoncée pour 2030."},{"id":"579-705","c":"8298","t":"Relancer la recherche dans le nucléaire du futur, comme les réacteurs de 4e génération (programme ASTRID) et la fusion nucléaire (projet international ITER)."},{"id":"579-706","c":"8298","t":"Mettre fin à tous les projets d’éoliennes actuels et futurs, sur terre comme sur mer."}]},{"id":"573","name":"Ecologie","ideas":[{"id":"573-707","c":"7804","t":"Créer un droit à la climatisation, en facilitant notamment les installations."},{"id":"573-708","c":"10357","t":"Interdire le versement de dividendes aux entreprises qui ne s’engagent pas résolument dans la transition écologique."},{"id":"573-709","c":"7806","t":"Créer une assemblée citoyenne du futur pour veiller à ce que chaque loi prenne en compte l’environnement."},{"id":"573-710","c":"7806","t":"Déployer des conventions citoyennes régionales et des assemblées locales pour le climat en partenariat avec les collectivités."},{"id":"573-711","c":"7806","t":"Créer un répertoire national des solutions écologiques, accessible à tous, avec des aides, des alternatives concrètes et des produits écoresponsables à prix plafonnés."},{"id":"573-712","c":"7806","t":"Interdire les nouvelles méga-surfaces commerciales."},{"id":"573-713","c":"7806","t":"Instaurer une Garantie universelle d’Assurance climatique, financée par les assurances."},{"id":"573-714","c":"7806","t":"Faire une grande loi Climat engageant tous les ministères, permettant l’adaptation et l’accompagnement des politiques publiques pour qu’elles ne dépassent plus les limites planétaires."},{"id":"573-715","c":"7806","t":"Lancer une loi contre la fast fashion, un score carbone obligatoire sur les produits, l'extinction des pubs lumineuses la nuit et la fin des plastiques à usage unique."},{"id":"573-716","c":"8413","t":"Plafonner les marges des raffineurs."},{"id":"573-717","c":"8413","t":"Augmenter les aides ciblées sur les gros rouleurs et les ménages les plus modeste pour pallier à la hausse du prix du carburant."},{"id":"573-718","c":"8413","t":"Sortir de la tarification européenne de l'électricité."},{"id":"573-719","c":"8254","t":"Respecter les accords de Paris à un rythme et avec des moyens discrétionnaires."},{"id":"573-720","c":"65","t":"Créer un défenseur des biens communs chargé de produire et publier un rapport annuel."},{"id":"573-721","c":"65","t":"Garantir un accès respectueux à la nature pour tous en rétablissant l’accès aux sentiers balisés grâce à la mise en place de servitudes de passage encadrées."},{"id":"573-722","c":"65","t":"Engager un plan global de rénovation des infrastructures pour les adapter au changement climatique."},{"id":"573-723","c":"65","t":"Inscrire dans la Constitution le principe de la « règle verte », selon laquelle on ne prélève pas davantage à la nature de ce qu’elle est en état de reconstituer."},{"id":"573-724","c":"65","t":"Redécouper les Régions à partir des bassins versants et leur confier l’eau comme première responsabilité."},{"id":"573-725","c":"65","t":"Faire des Outre-mer des territoires pilotes de la plannification écologique et des circuits-courts : autonomie énergétique et 100 % renouvelable, autosuffisance alimentaire, politique maritime, protection de la biodiversité."},{"id":"573-726","c":"65","t":"Lancer un plan massif de 200 Md€ d’investissements écologiquement et socialement utiles."},{"id":"573-727","c":"65","t":"Limiter la taille, le poids et les dimensions des SUV autorisés à la vente et développer la construction française de véhicules électriques légers."},{"id":"573-728","c":"65","t":"Abolir l’obsolescence programmée et allonger les durées de garantie légale des produits."},{"id":"573-729","c":"65","t":"Interdire les coupes rases sauf en cas d’impasse sanitaire avérée."},{"id":"573-730","c":"7805","t":"Lancer un grand plan pour climatiser massivement les infrastructures qui accueillent des personnes fragiles, écoles, crèches, hôpitaux, grâce au doublement du Fonds vert."},{"id":"573-731","c":"7805","t":"Concentrer l'action climatique sur ce qui réduit vraiment les émissions et crée de la croissance : fret de marchandises, rénovation, grande industrie."},{"id":"573-732","c":"7805","t":"Accélérer la décarbonation du pays et investir massivement dans la capture de carbone pour limiter l'ampleur du réchauffement."},{"id":"573-733","c":"7805","t":"Lancer un plan baignade national pour rendre baignables toutes nos rivières et rénover nos piscines."},{"id":"573-734","c":"7805","t":"Multiplier les plantations d'arbres dans nos villes et lever les règles d'urbanisme qui freinent l'adaptation des espaces publics."},{"id":"573-735","c":"7805","t":"Créer un DATAR 2.0, opérateur unique de l'adaptation des territoires au changement climatique."},{"id":"573-736","c":"8038","t":"Mettre en place une politique nationale de protection et de développement des continuités écologiques."},{"id":"573-737","c":"8038","t":"Renforcer la trajectoire de la Zéro artificialisation nette (ZAN)."},{"id":"573-738","c":"8038","t":"Abandonner les projets menaçant les zones humides."},{"id":"573-739","c":"8038","t":"Adopter et financer une stratégie de restauration de la biodiversité."},{"id":"573-740","c":"8038","t":"Refonder le service public de suivi et de protection de la nature."},{"id":"573-741","c":"8038","t":"Défendre, étendre et financer les parcs et les réserves naturels."},{"id":"573-742","c":"8038","t":"Interdire l’ensemble des polluants éternels (PFAS) et des perturbateurs endoctriniens."},{"id":"573-743","c":"8038","t":"Faire appliquer systématiquement le principe pollueur-payeur."},{"id":"573-744","c":"8038","t":"Améliorer la dépollution des sols et des eaux et l’indemnisation des victimes du chlordécone."},{"id":"573-745","c":"8038","t":"Interdire l’usage du plomb laminé en France."},{"id":"573-746","c":"8038","t":"Décréter un moratoire sur tous les projets de méga-bassine."},{"id":"573-747","c":"8038","t":"Rendre applicable le droit à l’eau potable."},{"id":"573-748","c":"8038","t":"Mettre en place de grands travaux de rénovation des canalisations."},{"id":"573-749","c":"8038","t":"Interdire la chasse le dimanche, les jours fériés et les vacances."},{"id":"573-750","c":"8038","t":"Définir une personnalité juridique pour les animaux."},{"id":"573-751","c":"8038","t":"Lutter contre l’abandon des animaux domestiques."},{"id":"573-752","c":"8038","t":"Lancer un plan de dépollution de nos façades maritimes et des fonds marins."},{"id":"573-753","c":"8038","t":"Renforcer le service public forestier."},{"id":"573-754","c":"8038","t":"Adopter un statut de « commun forestier »."},{"id":"573-755","c":"8038","t":"Créer et maintenir une trame vieux bois."},{"id":"573-756","c":"8038","t":"Instaurer un « congé climatique » (5 jours maximum par an)."},{"id":"573-757","c":"8298","t":"Aggraver les sanctions contre la pratique des décharges sauvages."},{"id":"573-758","c":"8298","t":"Faire émerger une filière industrielle et de recherche dans le recyclage des plastiques afin d’atteindre l’objectif 2025 de 50 % de volume recyclés."},{"id":"573-759","c":"8298","t":"Faire de la France une pionnière de l’aviation bas carbone en la dotant du premier avion 100 % biokérosène avant 2030."}]},{"id":"482","name":"Agriculture","ideas":[{"id":"482-760","c":"10536","t":"Rompre les accords européens de libre-échange : CETA, Nouvelle-Zélande, Kenya, Ukraine, etc."},{"id":"482-761","c":"10536","t":"Se mobiliser pour une exception agricole au sein de l'OMC."},{"id":"482-762","c":"10536","t":"Sortir de la PAC et rétablir une politique agricole commune."},{"id":"482-763","c":"10536","t":"Suppression des droits de succession sur les 100 premiers hectares transmis aux jeunes agriculteurs."},{"id":"482-764","c":"10536","t":"Exiger l'étiquetage obligatoire du pays d'origine des produits et créer un label unique \" Produit en France\"."},{"id":"482-765","c":"10536","t":"Réserver aux producteurs français 50 % puis progressivement 80 % des commandes publiques."},{"id":"482-766","c":"10536","t":"Encourager les circuits courts et autoriser la vente libre de céréales entre producteurs et éleveurs pour limiter les marges des intermédiaires."},{"id":"482-767","c":"7806","t":"Réformer la PAC pour soutenir l’emploi et le revenu agricole, l’utilité écologique et l’agriculture familiale."},{"id":"482-768","c":"7806","t":"Rééquilibrer la répartition des quotas de pêche pour favoriser la pêche artisanale et côtière en créant des labels valorisant la pêche de proximité."},{"id":"482-769","c":"7806","t":"Réduire les intrants chimiques et soutenir les alternatives durables pour rendre les fermes plus autonomes."},{"id":"482-770","c":"7806","t":"Imposer des mesures miroirs aux importations agricoles, contre le dumping social, sanitaire et environnemental."},{"id":"482-771","c":"7806","t":"Faciliter l’accès au foncier pour protéger les terres agricoles et permettre l’installation de nouveaux agriculteurs, inciter la reprise d’exploitations en soutenant la transmission des exploitations agricoles et des activités de pêche entre générations."},{"id":"482-772","c":"7806","t":"Garantir le revenu des agriculteurs par la mise en place de prix planchers rémunérateurs, et en mettant fin aux contournements de la loi EGALIM."},{"id":"482-773","c":"7806","t":"Mettre à disposition des produits BIO à la cantine pour les enfants."},{"id":"482-774","c":"7806","t":"Rendre obligatoire l’affichage du Nutriscore et taxer davantage les boissons trop sucrées."},{"id":"482-775","c":"7806","t":"Mettre en place un Plan national pour l’Alimentation Solidaire pour permettre aux associations et aux bénéficiaires de récupérer plus facilement les invendus."},{"id":"482-776","c":"7806","t":"Lancer un grand plan national pour lancer la résilience des forêts."},{"id":"482-777","c":"7806","t":"Réformer la gestion privée des forêts."},{"id":"482-778","c":"7806","t":"Miser sur une filière bois française durable, ancrée dans les territoires."},{"id":"482-779","c":"7806","t":"Lancer un Pacte bleu pour les océans."},{"id":"482-780","c":"7806","t":"Refuser les méga-bassines."},{"id":"482-781","c":"7806","t":"Instaurer une tarification sociale de l’eau, via les collectivités, avec des aides automatiques pour les foyers dont la facture dépasse 3 % des revenus."},{"id":"482-782","c":"7806","t":"Éliminer les produits chimiques dangereux en interdisant les pesticides les plus néfastes, glyphosate, néonicotinoïdes tueurs d’abeilles et objets du quotidien contenant des PFAS."},{"id":"482-783","c":"8254","t":"Garantir aux paysans des prix respectueux de leur travail et mettre un terme aux marges abusives de la grande distribution."},{"id":"482-784","c":"8254","t":"Lutter contre l’artificialisation des terres agricoles."},{"id":"482-785","c":"8254","t":"Installer une nouvelle génération d'agriculteurs pour faire face aux départs à la retraite conséquents à venir d'ici à 10 ans."},{"id":"482-786","c":"8254","t":"Lutter contre les effets néfastes de la stratégie européenne \" de la ferme à la fourchette \" qui menace la souveraineté européenne."},{"id":"482-787","c":"8254","t":"Faire du redressement de la balance commerciale agricole une priorité absolue."},{"id":"482-788","c":"8254","t":"Mise en place d'un plan de soutien spécifique pour l'agriculture biologique."},{"id":"482-789","c":"8254","t":"Faire de la prévention du suicide des agriculteurs une cause nationale."},{"id":"482-790","c":"8254","t":"Protéger l'agriculture française en l'excluant de tous les traités de libre-échange, qu'ils soient déjà signés ou en projet."},{"id":"482-791","c":"8254","t":"Interdire les importations de produits agricole ne respectant pas les normes de production françaises."},{"id":"482-792","c":"8254","t":"Aucune interdiction de produits phytosanitaires sans alternatives."},{"id":"482-793","c":"8254","t":"Atteindre 80% de produits français dans les cantines."},{"id":"482-794","c":"8039","t":"En finir avec les surtranspositions françaises, l’alignement réglementaire avec le marché commun, et la mise en œuvre de clauses miroirs obligatoires pour les produits importés."},{"id":"482-795","c":"8039","t":"Transformer la PAC pour qu'elle redevienne une politique agricole, recentrée sur la souveraineté alimentaire, la production, et l’augmentation de nos capacités exportatrices."},{"id":"482-796","c":"8039","t":"Autoriser des nouvelles techniques génomiques (NTG), l’usage raisonné des phytosanitaires sur base scientifique, et une réduction de la part des aides conditionnées à des critères idéologiques."},{"id":"482-797","c":"8039","t":"Proposer une réforme profonde du système de rémunération agricole : transfert d’une part des charges vers la valeur ajoutée pour améliorer les revenus nets et une juste rémunération des services environnementaux rendus par les agriculteurs et forestiers (stockage du carbone, entretien des écosystèmes)."},{"id":"482-798","c":"8039","t":"Relancer une politique industrielle fondée sur les productions agricoles et forestières (industries de 1re et 2e transformation sur tout le territoire, circuits courts soutenus, développement des filières biomasse, bois, fibres, énergie, transformation alimentaire locale), reconstruire une filière française d’engrais azotés décarbonés, mobiliser l’agriculture dans une stratégie géopolitique : diplomatie du blé, sécurisation des filières, souveraineté logistique."},{"id":"482-799","c":"8039","t":"Proposer une simplification radicale du statut de l’exploitation agricole, avec un cadre unique qui autorise, dans une même entité, la production agricole, forestière, énergétique, la transformation, le tourisme rural, la gestion du foncier et la participation aux objectifs climatiques."},{"id":"482-800","c":"8039","t":"Débureaucratisation massive (suppression des normes redondantes, guichet numérique unique, autonomie locale sur les modalités d’application)."},{"id":"482-801","c":"8039","t":"Remettre à plat le carcan normatif viticole, notamment dans les AOC, pour favoriser l’innovation, les cépages résistants, les usages du biocontrôle."},{"id":"482-802","c":"8039","t":"Fonder la gestion de l’eau sur la subsidiarité : les bassines sont possibles lorsqu’elles sont techniquement justifiées et localement décidées."},{"id":"482-803","c":"65","t":"Créer 300 000 emplois agricoles."},{"id":"482-804","c":"65","t":"Garantir des prix rémunérateurs aux producteurs par des prix planchers pour les agriculteurs, interdire les ventes à perte et mettre en place une caisse de défaisance pour reprendre les dettes agricoles des convertis au 100 % bio."},{"id":"482-805","c":"65","t":"Refonder la PAC et réorienter les aides publiques agricoles pour favoriser la production écologiquement soutenable."},{"id":"482-806","c":"65","t":"Faire une réforme agraire pour encourager l’installation de nouveaux agriculteurs et permettre le développement d’un tissu de nombreuses exploitations à taille humaine."},{"id":"482-807","c":"65","t":"Mettre en place un plan de protection généralisée du foncier agricole, forestier."},{"id":"482-808","c":"65","t":"Planifier la réduction progressive des doses d’engrais et de pesticides, interdire immédiatement les plus dangereux (glyphosate, néonicotinoïdes) et l’importation de productions qui en contiennent."},{"id":"482-809","c":"65","t":"Instaurer un protectionnisme écologique en fonction des conditions de production et de rémunération du travail agricole."},{"id":"482-810","c":"65","t":"Limiter le prix final des produits alimentaires en fixant des coefficients multiplicateurs et en encadrant les marges des industries agro-alimentaires et de la grande distribution."},{"id":"482-811","c":"65","t":"Interdire les fermes-usines."},{"id":"482-812","c":"7805","t":"Instaurer la règle de \"zéro surtransposition agricole\"."},{"id":"482-813","c":"7805","t":"Lancer un grand plan de transmission et de modernisation."},{"id":"482-814","c":"7805","t":"Créer 100 territoires de souveraineté alimentaire."},{"id":"482-815","c":"7805","t":"Inscrire le développement agricole dans la Charte de l'environnement."},{"id":"482-816","c":"7803","t":"Inscrire l’agriculture comme intérêt fondamental de la Nation dans la Constitution et supprimer le principe de précaution de la Charte de l’environnement."},{"id":"482-817","c":"7803","t":"Interdire les surtranspositions françaises des normes européennes en matière agricole, aligner les règles applicables aux élevages sur le socle européen et supprimer le ZAN (Zéro Artificialisation Nette) des sols."},{"id":"482-818","c":"7803","t":"Supprimer l’OFB et reprendre le contrôle politique des agences ; appliquer à l’ANSES le principe de reconnaissance mutuelle pour les produits déjà autorisés dans plusieurs États européens."},{"id":"482-819","c":"7803","t":"Faire de l’eau une ressource agricole stratégique, reconnaître le stockage de l’eau comme un intérêt général majeur et instaurer des délais d’instruction opposables à l’administration"},{"id":"482-820","c":"7803","t":"Moderniser les exploitations et relancer la productivité agricole en facilitant l’investissement, l’innovation et l’adoption de nouvelles techniques agronomiques."},{"id":"482-821","c":"7803","t":"Faciliter la transmission des exploitations et l’installation des jeunes agriculteurs, notamment par un différé d’imposition et une dissociation facilitée entre foncier et outil de production."},{"id":"482-822","c":"7803","t":"Lutter contre l’agribashing en supprimant les financements publics aux associations organisant des actions de déstabilisation, des recours dilatoires systématiques ou des violences contre les agriculteurs."},{"id":"482-823","c":"7803","t":"Sécuriser les débouchés agricoles en utilisant davantage la commande publique et en renforçant la compétitivité de l’industrie agroalimentaire."},{"id":"482-824","c":"7803","t":"Refonder la PAC autour de la souveraineté alimentaire et du revenu agricole, en maintenant une PAC pleinement européenne et en orientant davantage les aides vers les productions et filières stratégiques."},{"id":"482-825","c":"7803","t":"Rééquilibrer la chaîne de valeur et imposer la réciprocité commerciale, en renforçant les contrôles contre les pratiques abusives de la distribution et en soumettant les produits importés aux mêmes exigences que les productions françaises."},{"id":"482-826","c":"10360","t":"Lutter contre l'inégalité des enfants devant la qualité alimentaire : mettre la grande distribution devant ses responsabilités par rapport aux circuits courts et aux bonus qui doivent être donnés aux consommateurs qui achètent des produits français."}]}]},{"id":"479","name":"Europe & international","subs":[{"id":"480","name":"Affaires étrangères & diplomatie","ideas":[{"id":"480-827","c":"10536","t":"Sortir du commandement militaire intégré de l'OTAN"},{"id":"480-828","c":"10536","t":"S'engager pour la paix en Ukraine et relancer un partenariat avec la Russie."},{"id":"480-829","c":"10536","t":"Engager la France pour un accord de paix durable entre Israel et la Palestine."},{"id":"480-830","c":"10536","t":"Affirmer la présence française dans la zone Asie-Pacifique, face à la menace chinoise grandissante."},{"id":"480-831","c":"10536","t":"Lancer un grand partenariat avec l'Afrique, en renonçant à la repentance et aux leçons de morale."},{"id":"480-832","c":"10536","t":"Placer l'AFD sous le contrôle du ministère des affaires étrangères et recentrer ses aides sur les pays francophones."},{"id":"480-833","c":"10536","t":"Faire respecter avec intransigeance le statut du français dans les institutions internationales."},{"id":"480-834","c":"65","t":"Réaffirmer que l’ONU est le seul organe légitime pour la sécurité collective."},{"id":"480-835","c":"65","t":"Porter au sein du FMI, de la Banque mondiale, de l’OMC des propositions de rupture avec le néolibéralisme international et réinvestir la conférence des Nations unies sur le commerce et le développement."},{"id":"480-836","c":"65","t":"Renforcer l’organisation internationale pour les migrations et le Haut commissariat des Nations unies pour les réfugiés et organiser une conférence annuelle sur les migrations."},{"id":"480-837","c":"65","t":"Consacrer 0,7 % du revenu national brut à une aide publique au développement pour sortir du néolibéralisme."},{"id":"480-838","c":"65","t":"Créer un réseau d’universités méditerranéennes et organiser un réseau méditerranéen de l’enseignement professionnel."},{"id":"480-839","c":"65","t":"Défendre l’usage du français dans les institutions internationales."},{"id":"480-840","c":"65","t":"Abroger les accords de libre-échange en vigueur (comme avec la Nouvelle-Zélande, le Canada, le Japon)."}]},{"id":"556","name":"Union Européenne","ideas":[{"id":"556-841","c":"10357","t":"Suspendre l'accord d'association entre l'Union européenne et Israël."},{"id":"556-842","c":"10357","t":"Interdire le commerce avec les colonies israéliennes."},{"id":"556-843","c":"7806","t":"Proposer un nouveau contrat de souveraineté qui clarifie la répartition des compétences entre les échelons européens, nationaux, régionaux et locaux, un véritable pacte girondin pour sortir de l’impuissance actuelle."},{"id":"556-844","c":"7806","t":"Augmenter massivement le budget de l’Union européenne pour lui permettre de lancer des politiques publiques et dépasser le rôle de puissance exclusivement normative, et attribuer à l’UE des ressources propres nouvelles."},{"id":"556-845","c":"7806","t":"Mettre en place un fonds européen de défense de 500 Md€ via un emprunt commun, pour investir massivement dans nos capacités industrielles, en réservant les investissements européens aux productions européennes (EDIP)."},{"id":"556-846","c":"7806","t":"Etendre la dissuasion nucléaire française aux autres pays de l'UE, en conservant la souveraineté française sur la décision de l'emploi."},{"id":"556-847","c":"7806","t":"Augmenter l'aide militaire à l'Ukraine et notre soutien aux alliés européens comme la Moldavie et l'Arménie."},{"id":"556-848","c":"7806","t":"Porter d’ici 2030 un grand traité de réunification européenne qui sera aussi un traité de refondation institutionnelle : clarifier et démocratiser le fonctionnement de l’UE."},{"id":"556-849","c":"7806","t":"Porter un Buy European Act pour prioriser les productions européennes dans les marchés publics."},{"id":"556-850","c":"7806","t":"Créer un label européen pour l'épargne pour garantir que l'épargne des Européens finance des entreprises et des projets en Europe, plutôt que des économies extra européennes."},{"id":"556-851","c":"8413","t":"Construire un pôle de défense européenne qui soit capable de préparer la suite de ce qui va se passer en Ukraine."},{"id":"556-852","c":"8254","t":"Réduire de moitié la contribution de la France au budget de l’UE."},{"id":"556-853","c":"10767","t":"Suspendre l'accord d'association entre l'Union européenne et Israël."},{"id":"556-854","c":"65","t":"Utiliser le droit de veto de la France, par exemple pour refuser tous les nouveaux accords de libre-échange."},{"id":"556-855","c":"65","t":"Abroger les accords de libre-échange en vigueur (comme avec la Nouvelle-Zélande, le Canada, le Japon)."},{"id":"556-856","c":"65","t":"Conditionner la contribution française au budget de l’Union européenne."},{"id":"556-857","c":"65","t":"Cesser d’appliquer unilatéralement les normes incompatibles avec nos engagements écologiques et sociaux, telles que la directive sur le détachement des travailleurs, les règles budgétaires, les règles de la concurrence, la libre circulation des capitaux."},{"id":"556-858","c":"65","t":"Suspendre la participation (opt-out) de la France à certains programmes comme l’Europe de la défense et s’opposer à la reconduction d’un Commissaire européen à la Défense dont le poste participe à l’édification d’une Europe de la guerre."},{"id":"556-859","c":"65","t":"Modifier les traités européens afin de permettre à la France de s’affranchir de certaines règles européennes et de préserver ses intérêts politiques, sociaux et industriels."},{"id":"556-860","c":"7805","t":"Ne plus dissocier la sécurité commerciale, étrangère et militaire."},{"id":"556-861","c":"7805","t":"Protéger le marché européen face à la concurrence déloyale chinoise, en imposant transferts de technologie, quotas de production et joint-ventures dans les secteurs stratégiques et permettre l'émergence de géants des industries automobile, sidérurgique et nucléaire."},{"id":"556-862","c":"7805","t":"Achever la mise en œuvre du marché unique européen en supprimant les spécifications nationales qui agissent comme des droits de douane, pour permettre aux entreprises françaises d'opérer sur un marché de 450 millions de consommateurs."},{"id":"556-863","c":"7805","t":"Construire une Union européenne des marchés de capitaux capable de rivaliser avec les géants américains."},{"id":"556-864","c":"7805","t":"Mettre en place un Buy European Tech Act et des achats technologiques groupés entre Etats membres."}]}]},{"id":"627","name":"Gouvernance & République","subs":[{"id":"716","name":"Démocratie, élections et pouvoir législatif","ideas":[{"id":"716-865","c":"7804","t":"Proposer un référendum une fois par an."},{"id":"716-866","c":"7806","t":"Investir le Premier ministre par un vote de confiance de l’AN et instaurer la « motion de censure constructive » pour mettre fin au 49.3 (censurer un gouvernement exigera de proposer un successeur)."},{"id":"716-867","c":"7806","t":"Renforcer le contrôle du Parlement sur l’action gouvernementale : transparence sur les décrets d’application, évaluation rigoureuse du budget, droit d’enquête élargi..."},{"id":"716-868","c":"7806","t":"Instaurer la proportionnelle, de préférence par circonscriptions régionales avec un fléchage départemental des candidats."},{"id":"716-869","c":"7806","t":"Supprimer l’article 16 de la Constitution (pouvoirs exceptionnels du Président en temps de crise) et renforcer le pouvoir d’initiative et d’amendement du Parlement (fin de l’article 40), réformer le Conseil constitutionnel pour renforcer son impartialité et ses moyens."},{"id":"716-870","c":"7806","t":"Lancer en parallèle une grande convention citoyenne qui jettera les bases d’une assemblée constituante pour changer la Constitution."},{"id":"716-871","c":"7806","t":"Ouvrir le droit de vote à 16 ans et pour les étrangers extra-communautaires aux élections locales, généraliser l’inscription automatique sur les listes électorales."},{"id":"716-872","c":"7806","t":"Renforcer la démocratie locale en instaurant une loi pluriannuelle des finances locales, en renforçant le pouvoir d’imposition des collectivités et en élisant les conseils communautaires des intercommunalités au suffrage universel direct par scrutin de liste paritaire."},{"id":"716-873","c":"7806","t":"Voter une nouvelle loi de décentralisation."},{"id":"716-874","c":"7806","t":"Renforcer le service public de l’audiovisuel et l’indépendance des médias en assurant un financement stable de la presse via une taxe sur les géants du numérique, lutter contre les campagnes de désinformation en inscrivant un délit de désinformation organisée dans la loi de 1881."},{"id":"716-875","c":"7806","t":"Instaurer un droit d’initiative citoyenne."},{"id":"716-876","c":"7806","t":"Réformer le financement des partis politiques en créant un « bon pour la démocratie »."},{"id":"716-877","c":"7806","t":"Revaloriser les salaires des agents, recruter là où les besoins sont criants et renforcer l’attractivité de la fonction publique."},{"id":"716-878","c":"8254","t":"Inscrire la « priorité nationale » dans la Constitution par référendum pour l’accès aux logements sociaux et aux allocations."},{"id":"716-879","c":"65","t":"Rassembler une Assemblée constituante par un référendum (art 11 de la Constitution)."},{"id":"716-880","c":"65","t":"Faire rédiger la nouvelle Constitution par les citoyens membres de cette Assemblée élus ou tirés au sort."},{"id":"716-881","c":"65","t":"Passer à une 6e République qui soit un régime parlementaire : élire l’Assemblée nationale au scrutin proportionnel, obliger le gouvernement à rendre des comptes devant le Parlement et abolir le 49.3."},{"id":"716-882","c":"65","t":"Imposer la transparence des agendas des membres des bureaux des Parlements."},{"id":"716-883","c":"65","t":"Rendre inéligible toute personne condamnée pour corruption."},{"id":"716-884","c":"65","t":"Durcir les règles contre les conflits d’intérêts et interdire le pantouflage."},{"id":"716-885","c":"65","t":"Allonger à 10 ans les périodes d’interdiction d’exercice d’une fonction privée après avoir exercé une activité dans la fonction publique relative au même secteur."},{"id":"716-886","c":"65","t":"Garantir des recrutements qui reflètent la diversité sociale dans les concours de la fonction publique."},{"id":"716-887","c":"65","t":"Supprimer le monopole du déclenchement de poursuites judiciaires par la seule administration fiscale pour toutes les affaires en cas de fraude."},{"id":"716-888","c":"65","t":"Mettre fin au monopole de la parole des patrons par le Medef et fonder la représentativité des organisations patronales sur la base d’élections des chefs d’entreprise."},{"id":"716-889","c":"65","t":"Organiser l’élection des administrateurs de la Sécurité sociale par les assurés eux-mêmes et leur donner le pouvoir de lever les cotisations."},{"id":"716-890","c":"65","t":"Réformer le financement de la vie politique et abaisser à 200€ le plafond des dons individuels aux partis politiques."},{"id":"716-891","c":"65","t":"Interdire la sous-traitance et la surfacturation de la mise en œuvre et de l’évaluation des politiques publiques à des cabinets de conseil privés."},{"id":"716-892","c":"65","t":"Abolir la réforme Macron du corps préfectoral et diplomatique."},{"id":"716-893","c":"65","t":"Instaurer le référendum d’initiative citoyenne pour révoquer des élus, proposer ou abroger une loi et modifier la Constitution."},{"id":"716-894","c":"65","t":"Instaurer le droit de vote à 16 ans."},{"id":"716-895","c":"65","t":"Reconnaitre le vote blanc, mettre en place le vote obligatoire et instaurer un seuil de votes exprimés pour valider une élection."},{"id":"716-896","c":"65","t":"Instaurer une procédure de parrainages citoyens pour l’élection présidentielle (en alternative aux 500 parrainages d’élus)."},{"id":"716-897","c":"65","t":"Interdire la sous-traitance des opérations de propagande électorale à des entreprises privées."},{"id":"716-898","c":"65","t":"Rendre obligatoire le recours au référendum en cas de modification de la Constitution ou d’adoption d’un nouveau traité européen."},{"id":"716-899","c":"65","t":"Rendre aux communes leur liberté de coopération."},{"id":"716-900","c":"65","t":"Donner à la Corse le statut garanti par l’article 74 de la Constitution."},{"id":"716-901","c":"65","t":"Rendre effectif le principe du non-cumul des mandats et des indemnités, y compris dans le temps."},{"id":"716-902","c":"65","t":"Faire voter une loi d’amnistie pour les syndicalistes, les Gilets jaunes, les militants pour la paix, les écologistes, les associatifs et les différents mouvements sociaux dans les Outre-mer, condamnés pour leur participation à la vie publique."},{"id":"716-903","c":"65","t":"Supprimer les mégarégions et les métropoles technocratiques, et revenir sur l’obligation d’appartenance des communes à des intercommunalités en abrogeant la loi portant sur la Nouvelle Organisation territoriale de la République (NOTRe)."},{"id":"716-904","c":"65","t":"Rééquilibrer la dotation globale de fonctionnement versée aux communes pour lutter contre les inégalités territoriales et l’indexer sur l’inflation."},{"id":"716-905","c":"65","t":"Refuser les fusions forcées de communes."},{"id":"716-906","c":"65","t":"Augmenter l’enveloppe budgétaire des communes rurales par la création d’un fonds de soutien communal notamment pour recruter et revaloriser les agents."},{"id":"716-907","c":"65","t":"Valoriser les emplois de secrétaires de mairies en favorisant le recrutement à temps complet et en développant des formations adaptées."},{"id":"716-908","c":"65","t":"Instaurer le scrutin de liste dans toutes les communes et imposer la parité dans le binôme maire – premier adjoint."},{"id":"716-909","c":"65","t":"Constitutionnaliser la non-marchandisation du corps humain et le droit fondamental de disposer de soi en toute circonstance."},{"id":"716-910","c":"7805","t":"Encadrer le droit d’amendement en conditionnant le dépôt d’un amendement à un groupe parlementaire."},{"id":"716-911","c":"7805","t":"Débattre en séance publique seulement les amendements examinés ou adoptés en commission."},{"id":"716-912","c":"7805","t":"Limiter le dispositif législatif à ce qui relève de la loi. Le reste doit être renvoyé au règlement (y compris au niveau des régions ou autres collectivités)."},{"id":"716-913","c":"7805","t":"Créer un système de présomption de légalité dans certains cas précisément définis."},{"id":"716-914","c":"7805","t":"Procéder à des abrogations massives afin de reconstruire un cadre réglementaire neuf, ciblé plutôt que général."},{"id":"716-915","c":"7803","t":"Élargir le champ du référendum en abaissant de 5 à 2,5 millions le nombre de signatures nécessaires pour déclencher un référendum d’initiative partagée."},{"id":"716-916","c":"7803","t":"Réviser la Constitution pour permettre, dans certains cas, de revenir sur une censure du Conseil constitutionnel par une réunion du Congrès ou un référendum."},{"id":"716-917","c":"7803","t":"Faire primer le droit français sur le droit européen dans certains cas."},{"id":"716-918","c":"8455","t":"Réduire le salaire du président de la République à un salaire équivalent au SMIC."},{"id":"716-919","c":"8455","t":"Réduire le budget de l’Élysée : 20 M€ d’économies réalisées."},{"id":"716-920","c":"8455","t":"Supprimer les privilèges : logements de fonction, chauffeurs, personnel. Maintien uniquement de la protection policière si nécessaire."},{"id":"716-921","c":"8455","t":"Baisser les hauts salaires politiques (cabinets ministériels, parlementaires, hauts fonctionnaires)."},{"id":"716-922","c":"8455","t":"Voter une « Loi de séparation de l’État et de l’argent » : limiter l’influence des grandes entreprises, des banques, des cabinets de conseil."},{"id":"716-923","c":"8298","t":"Organiser un référendum sur l’immigration, la sécurité et la justice."},{"id":"716-924","c":"8298","t":"Favoriser l’usage du référendum afin de faire adopter directement par le peuple français les mesures qui intéressent la Nation."},{"id":"716-925","c":"8298","t":"Instaurer un référendum obligatoire pour toute proposition de révision de la Constitution, ratification de traité européen ou élargissement de l’UE."},{"id":"716-926","c":"8298","t":"Instaurer la supériorité des nouvelles lois nationales sur tout texte international antérieur et sur tout acte dérivé qui en résulte en modifiant l’article 55 de la Constitution."},{"id":"716-927","c":"8298","t":"Permettre au Parlement d’avoir le dernier mot en cas d’inconstitutionnalité d’une loi par un vote du Parlement réuni en Congrès à la majorité des 3/5e."}]},{"id":"576","name":"Egalité, laïcité & droits individuels","ideas":[{"id":"576-928","c":"10536","t":"Interdire tous les signes religieux visibles dans le service public."},{"id":"576-929","c":"10536","t":"Conditionner l'ouverture d'une mosquée à la signature du Serment de fidélité à la République Française par l'imam et le président de l'association culturelle."},{"id":"576-930","c":"10536","t":"Suspendre les aides sociales pour les personnes récidivistes qui enfreignent les principes de laïcité."},{"id":"576-931","c":"10536","t":"Instaurer une peine de 10 ans de prison et 100 000 euros d'amende pour les prédicateurs subversifs et séditieux."},{"id":"576-932","c":"10536","t":"Fermer immédiatement toutes les associations ou lieux de culte qui refusent de signer la Charte de conformité de l'Islam."},{"id":"576-933","c":"7806","t":"Abolir progressivement les différents régimes dérogatoires à la loi de 1905 et aux lois laïques scolaires."},{"id":"576-934","c":"7806","t":"Recréer un rite de passage républicain et universel autour de la majorité pour remplacer le service militaire."},{"id":"576-935","c":"65","t":"Mettre en place un plan de séparation de l’Eglise et de l’État sur les territoires où ce n'est pas encore le cas : abroger le concordat d’Alsace-Moselle."},{"id":"576-936","c":"65","t":"Interdire aux élus locaux, parlementaires, ministres et préfets d’assister à des cérémonies religieuses au titre de leurs fonctions, ou de recevoir des titres religieux, et refuser l’attribution du titre de chanoine de Latran au président de la République."},{"id":"576-937","c":"65","t":"Refuser les financements publics pour la construction d’édifices religieux, d’activités cultuelles et d’établissements confessionnels."},{"id":"576-938","c":"65","t":"Abroger les divers statuts spécifiques en vigueur dans les Outre-mer."}]},{"id":"1134","name":"Numérique et IA","ideas":[{"id":"1134-939","c":"7804","t":"Faire émerger des géants de l’intelligence artificielle en France, grâce à des investissments privés notamment."},{"id":"1134-940","c":"10536","t":"Créer un fonds souverain IA doté de plusieurs milliards d'euros financé par l'Etat, la BPI et des investisseurs privés."},{"id":"1134-941","c":"10536","t":"Déployer un cloud souverain ultra sécurisé indépendant des solutions étrangères"},{"id":"1134-942","c":"10536","t":"Recréer un écosystème de logiciels sous licences gratuites et maîtrises d'oeuvres étatiques françaises."},{"id":"1134-943","c":"10536","t":"Revoir la culture Open Source et Open Data de nos laboratoires et de l'Etat."},{"id":"1134-944","c":"10536","t":"Assumer une préférence nationale dans les marchés de l'IA."},{"id":"1134-945","c":"10536","t":"Soutenir massivement les start-ups françaises pour éviter leur fuite vers la Silicon Valley."},{"id":"1134-946","c":"10536","t":"Rendre obligatoire une domiciliation fiscale en France des agences des géants du numérique."},{"id":"1134-947","c":"10536","t":"Aider à la relocalisation ou à l'implantation industrielle de secteurs critiques tels que les semi-conducteurs, les supercalculateurs etc."},{"id":"1134-948","c":"10536","t":"Autoriser une extraction \" decomplexée \" des terres rares et matières premières sur nos territoires et fonds marins."},{"id":"1134-949","c":"10536","t":"Adapter le système éducatif à l'IA : assurer une formation IA des enseignants, un cursus IA au collège et création d'un pôle universitaire IA de référence."},{"id":"1134-950","c":"10536","t":"Créer une agence nationale de l'éthique et de la sécurité des IA."},{"id":"1134-951","c":"7806","t":"Créer une grande Agence industrielle du numérique et de l’IA, avec un budget financé par France 2030, la BPI et une hausse ciblée de la taxe GAFAM, qui pilotera un plan national d’investissement dans les infrastructures algorithmiques d’intérêt général : logiciels libres, données ouvertes, IA souveraine, gouvernance partagée..."},{"id":"1134-952","c":"7806","t":"Ouvrir un campus international de l’IA pour former ensemble codeurs, juristes et scientifiques."},{"id":"1134-953","c":"7806","t":"Faire de l’IA un levier de transformation des services publics en investissant massivement dans les usages à fort impact social (santé, éducation, transition écologique)."},{"id":"1134-954","c":"7806","t":"Créer une Autorité indépendante de protection des mineurs en ligne chargée de réguler les contenus numériques accessibles aux mineurs et qui mettra en place un cadre strict incluant la vérification de l’âge et la classification des contenus."},{"id":"1134-955","c":"7806","t":"Interdire les réseaux sociaux pour les moins de 15 ans."},{"id":"1134-956","c":"7806","t":"Bannir TikTok."},{"id":"1134-957","c":"7806","t":"Impulser un traité international de l'IA qui poserait les bases d'une régulation internationale des usages de l'IA dans les domaines à très haut risque."},{"id":"1134-958","c":"8254","t":"Mettre en place un contrôle strict avec facultés d'interdiction pour des intérêts étrangers ou non européens de racheter des entreprises françaises numériques stratégiques."},{"id":"1134-959","c":"8254","t":"Mettre en place au niveau de l'UE ou de l'OCDE de taxes extraordinaires pour les entreprises étrangères du numérique."},{"id":"1134-960","c":"8254","t":"Contrôler de manière accrue le respect intégral par les entreprises numériques étrangères du droit français et européen."},{"id":"1134-961","c":"8254","t":"Mettre en place une couverture numérique plus large du territoire afin de supprimer les zones blanches."},{"id":"1134-962","c":"8254","t":"Instaurer une politique volontariste de lutte contre l'illettrisme numérique, en particulier chez les personnes âgées."},{"id":"1134-963","c":"8254","t":"Rendre obligatoire l'hébergement des données des français, des entreprises françaises et des services publics en France et dans l'Union Européenne par des opérateurs français ou européens."},{"id":"1134-964","c":"65","t":"Garantir le droit à un accès minimal gratuit à internet."},{"id":"1134-965","c":"65","t":"Garantir la neutralité du Net, c’est-à-dire l’accès légal de chacun et l’égalité de traitement."},{"id":"1134-966","c":"7805","t":"Rendre obligatoire le consentement aux algorithmes dans les suggestions de contenus sur les plateformes."},{"id":"1134-967","c":"7805","t":"Instaurer une « réserve algorithmique pré-électorale » sur les plateformes pendant une période définie en amont du scrutin afin d’éviter toute manipulation et de préserver la sincérité des votes."},{"id":"1134-968","c":"7805","t":"Mettre rapidement et effectivement en place, au niveau européen ou, à défaut, à l’échelle nationale, une majorité numérique conditionnant l’accès aux réseaux sociaux."},{"id":"1134-969","c":"7805","t":"Développer une infrastructure d'IA européenne souveraine en soutenant nos champions et en doublant notre capacité de calcul en cinq ans."},{"id":"1134-970","c":"7805","t":"Simplifier le cadre juridique européen applicable à l'IA, sans renoncer à une régulation éthique et protectrice des enfants."},{"id":"1134-971","c":"7805","t":"Créer un \"livret capital France\" pour mobiliser l'épargne des Français et utiliser la capitalisation retraite pour financer nos champions technologiques."},{"id":"1134-972","c":"7805","t":"Adapter l'enseignement, le recrutement et la formation continue à l'IA, en instaurant un droit à la reconversion pour les métiers menacés."},{"id":"1134-973","c":"7805","t":"Massifier la production d'ingénieurs, de 40 000 à 100 000 par an en cinq ans."},{"id":"1134-974","c":"7803","t":"Reconquérir la souveraineté sur les données, en imposant l’hébergement en Europe des données sensibles et en créant de grands espaces de données français et européens."},{"id":"1134-975","c":"7803","t":"Former massivement les Français à l’IA, avec plusieurs millions d’actifs formés, un doublement du nombre d’ingénieurs spécialisés et l’intégration de l’IA dans les cursus du supérieur."},{"id":"1134-976","c":"7803","t":"Attirer et faire revenir les meilleurs talents, grâce à des dispositifs dédiés de retour en France et à un visa « Talents Tech »."},{"id":"1134-977","c":"7803","t":"Lever les freins réglementaires à l’innovation, en refusant toute surtransposition européenne et en expérimentant des dérogations au RGPD et à l’AI Act pour les projets stratégiques."},{"id":"1134-978","c":"7803","t":"Faire émerger des champions français et européens de l’IA, en comblant le déficit de financement et en développant des infrastructures souveraines, notamment des data centers."},{"id":"1134-979","c":"7803","t":"Déployer massivement l’IA dans les entreprises, notamment les PME et ETI, grâce à un « Starter Pack IA », au suramortissement des investissements et à la formation des salariés."},{"id":"1134-980","c":"7803","t":"Simplifier l’État grâce à l’IA, en automatisant les tâches répétitives pour mobiliser l’équivalent de 250 000 agents publics, dont 125 000 redéployés sur le terrain et 125 000 départs non remplacés, avec un objectif d’environ 15 Md€ d’économies nettes annuelles."},{"id":"1134-981","c":"7803","t":"Donner à chaque Français un assistant administratif unique, « Marianne », et utiliser davantage l’IA pour lutter contre la fraude et simplifier les démarches administratives."},{"id":"1134-982","c":"7803","t":"Faire de l’IA un pilier de la souveraineté et de la sécurité nationales, en multipliant par cinq les moyens consacrés à l’IA de défense et en renforçant la cybersécurité des hôpitaux, collectivités et infrastructures vitales."},{"id":"1134-983","c":"8298","t":"Imposer par la loi que les données sensibles des Français ainsi que les données stratégiques de l’État et du secteur privé soient hébergées et sécurisées en France sur des solutions souveraines."},{"id":"1134-984","c":"8298","t":"Garantir une connexion haut débit à chaque Français et chaque entreprise sur tout le territoire."},{"id":"1134-985","c":"8298","t":"Accélérer la numérisation des services de l’État et la mise à disposition des données."}]}]},{"id":"506","name":"Réformes de l'Etat","subs":[{"id":"554","name":"Administrations et opérateurs","ideas":[{"id":"554-986","c":"8039","t":"Digitaliser le service public pour réduire la masse salariale tout en gardant une présence humaine pour répondre aux citoyens."},{"id":"554-987","c":"8039","t":"Renforcer le Conseil National d’Évaluation des Normes et le saisir systématiquement en amont pour que son avis soit suivi."},{"id":"554-988","c":"8039","t":"Revoir tous les codes pour les réduire."},{"id":"554-989","c":"8039","t":"Diviser Bercy en trois entre le budget, les impôts, l’économie."},{"id":"554-990","c":"8039","t":"Confier à un ministre rattaché à Matignon de supprimer des textes, et mandater une équipe à l’Élysée pour ne faire que cela."},{"id":"554-991","c":"8039","t":"Supprimer « l’agentialisation » et la régionalisation des services de l’État. Il ne doit plus y avoir qu’un seul interlocuteur au niveau déconcentré, le préfet et le sous-préfet."},{"id":"554-992","c":"8039","t":"Donner des moyens à l’État de contrôler le respect des normes. Des sanctions administratives, voire pénales doivent s’appliquer."},{"id":"554-993","c":"8039","t":"Supprimer l’ARS, la Dreal, la MRAE, la Dreets, et les préfectures disposeraient ‘équipes dont le rôle serait de veiller à la bonne application des normes par des contrôles a posteriori."},{"id":"554-994","c":"8039","t":"Interdire la surtransposition des textes européens."},{"id":"554-995","c":"7805","t":"Fusionner 4 agences pour recréer une DATAR 2.0, direction de l’aménagement du territoire et de l’adaptation au réchauffement, qui mobilisera des milliers de techniciens de l’adaptation aux côtés des collectivités pour construire les digues, retenues d’eau, infrastructures."},{"id":"554-996","c":"7805","t":"S'engager à ne pas produire de nouvelle norme sur le quinquennat."},{"id":"554-997","c":"7805","t":"Regrouper ou privatiser les agences et opérateurs de l'Etat enchevêtrés."},{"id":"554-998","c":"7805","t":"Simplifier les procédures."}]},{"id":"1135","name":"Fonction publique","ideas":[{"id":"1135-999","c":"7804","t":"Mettre en place un plan de départs volontaires de fonctionnaires, avec un objectif de 100 000 postes supprimés. Les ministères de l’éducation nationale, des armées, de la justice et de l’intérieur seront préservés.\nÉconomies : 7 Md€"},{"id":"1135-1000","c":"7804","t":"Assurer le non-remplacement de certains départs à la retraite pour les agents d’État."},{"id":"1135-1001","c":"7803","t":"Aligner complètement le temps de travail des agents publics sur le droit commun (1 607 heures par an), pour générer 4 Md€ d’économies."},{"id":"1135-1002","c":"7803","t":"Ne pas remplacer systématiquement les agents publics partants à la retraite pour les fonctions supports et améliorer la productivité par l’usage de l’IA pour supprimer au total 250 000 à 300 000 postes sur le quinquennat, avec des redéploiements d’agents sur le terrain."}]}]},{"id":"1129","name":"Education & Jeunesse","subs":[{"id":"1131","name":"Services de la petite enfance","ideas":[{"id":"1131-1003","c":"7803","t":"Favoriser la création de solutions de garde par le secteur privé pour chaque enfant avant trois ans."},{"id":"1131-1004","c":"7803","t":"Simplifier les normes pour construire et ouvrir des crèches plus vite."},{"id":"1131-1005","c":"7803","t":"Encourager les entreprises à financer des solutions de garde par deux mesures fiscales :\n• supprimer le plafond de 500 000 € qui limite aujourd’hui le crédit d’impôt famille dont bénéficient les entreprises finançant des places en crèche pour leurs salariés ;\n• relever de 2 421 € à 7 000 € par an le plafond d’exonération de cotisations sociales et d’impôt sur le revenu applicable à la participation financière versée par l’employeur à chaque salarié pour la garde de son enfant.\nCoût : 800M€."},{"id":"1131-1006","c":"7803","t":"Revaloriser les professionnels de la petite enfance (ouvrir un accès prioritaire au logement social à proximité de leur lieu de travail)."}]},{"id":"1132","name":"Périscolaire","ideas":[{"id":"1132-1007","c":"7805","t":"Instituer un \"droit de savoir\" pour permettre aux parents de saisir la police pour faire vérifier l'absence d'antécédents d'une personne entrant au contact de leur enfant."},{"id":"1132-1008","c":"7805","t":"Déployer les certificats d'honorabilité partout dans le périscolaire."},{"id":"1132-1009","c":"7805","t":"Mettre en place un \"choc de formation\"."}]},{"id":"528","name":"Education nationale","ideas":[{"id":"528-1010","c":"7804","t":"Maintenir le « choc des savoirs » pour élever le niveau scolaire et renforcer les fondamentaux."},{"id":"528-1011","c":"7804","t":"Soutenir la mesure de l’interdiction des réseaux sociaux pour les moins de 15 ans."},{"id":"528-1012","c":"7804","t":"Raccourcir les journées de travail à l’école aux dépens des vacances scolaires."},{"id":"528-1013","c":"7804","t":"Accorder davantage d’autonomie et de responsabilité aux établissements afin de répondre au problème des absences de professeurs non remplacés. Chaque établissement doit pouvoir trouver une organisation permettant d’assurer une permanence des enseignements, notamment pour les absences de courte durée."},{"id":"528-1014","c":"7804","t":"Créer un conseil de discipline pour le primaire."},{"id":"528-1015","c":"7804","t":"Etablir une échelle nationale des sanctions pour permettre au personnel éducatif et enseignant de prononcer plus facilement des sanctions quand les jeunes ne respectent pas les règles."},{"id":"528-1016","c":"10357","t":"Mettre en place un petit-déjeuner gratuit pour tous les élèves dans les établissements scolaires."},{"id":"528-1017","c":"10357","t":"Mieux rémunérer et former les accompagnants d’élèves en situation de handicap (AESH)."},{"id":"528-1018","c":"10357","t":"Garantir la présence d’un psychologue et d’une infirmière scolaires dans chaque établissement."},{"id":"528-1019","c":"10357","t":"Permettre à chaque élève de participer à une classe de découverte au cours de sa scolarité."},{"id":"528-1020","c":"10357","t":"Relancer la politique d'éducation prioritaire."},{"id":"528-1021","c":"10357","t":"Remettre à plat le système de bourses et d'aides sociales."},{"id":"528-1022","c":"10357","t":"Conditionner le financement des établissements privés sous contrat à des obligations de mixité sociale."},{"id":"528-1023","c":"7806","t":"Repenser en profondeur Parcoursup."},{"id":"528-1024","c":"7806","t":"Proposer un modèle de financement renforcé pour les universités."},{"id":"528-1025","c":"7806","t":"Mieux encadrer l’enseignement supérieur privé lucratif, avec transparence des financements, contrôle pédagogique renforcé et aides publiques conditionnées."},{"id":"528-1026","c":"7806","t":"Mettre fin aux inégalités géographiques dans l’accès aux études supérieures : création d’une aide nationale pour compenser les frais liés à l’éloignement et développement de formations délocalisées."},{"id":"528-1027","c":"7806","t":"Réinventer les bourses étudiantes."},{"id":"528-1028","c":"7806","t":"Réduire le nombre d’élèves par enseignant."},{"id":"528-1029","c":"7806","t":"Revaloriser le salaire de tous les enseignants de manière continue et planifiée sur 5 ans."},{"id":"528-1030","c":"7806","t":"Intégrer les établissements privés sous contrat à la carte scolaire."},{"id":"528-1031","c":"8254","t":"Valoriser les filières professionnelles et manuelles grâce à un collège modulaire."},{"id":"528-1032","c":"8254","t":"Abrogation de la réforme Blanquer du Baccalauréat."},{"id":"528-1033","c":"8254","t":"Port de l'uniforme au primaire et au collège."},{"id":"528-1034","c":"8254","t":"Grande réforme de l'enseignement du primaire : recentrage autour d'un tronc commun et hausse conséquente du volume horaire."},{"id":"528-1035","c":"8254","t":"Mise en place d'un plan d'urgence éducative pour l'Outre-Mer, en particulier la Guyane et Mayotte"},{"id":"528-1036","c":"8254","t":"Suppression de toute forme de \" discrimination positive\"."},{"id":"528-1037","c":"8254","t":"Retour aux principes de la loi Ciotti de 2010 : valorisation de l'assiduité, instauration de peines plancher et généralisation de la vidéoprotection."},{"id":"528-1038","c":"8254","t":"Interdiction légale du port du voile islamique."},{"id":"528-1039","c":"8254","t":"Revalorisation des professeurs du primaire au lycée de 3% par an chaque année du quinquennat."},{"id":"528-1040","c":"8254","t":"Suppression des instituts nationaux supérieurs du professorat et de l'éducation."},{"id":"528-1041","c":"8039","t":"Abroger la carte scolaire qui enferme les familles dans leur quartier pour proposer un libre choix de l’école."},{"id":"528-1042","c":"8039","t":"Instaurer progressivement un chèque-éducation : un financement public équivalent, que la famille choisisse l’enseignement public ou privé."},{"id":"528-1043","c":"8039","t":"Liberté donnée aux chefs d’établissement de recruter leurs équipes pédagogiques, d’appliquer leurs méthodes, de gérer leur budget, de refuser des élèves pouvant nuire au collectif."},{"id":"528-1044","c":"8039","t":"Instauration d’un certificat de fin de primaire dont la validation conditionnera l’entrée au collège."},{"id":"528-1045","c":"8039","t":"Instaurer le grec, le latin et la philosophie dès le primaire."},{"id":"528-1046","c":"8039","t":"Augmenter de 20 % les rémunérations en 5 ans, proposition conditionnée à une réorganisation : autonomie accrue, présence renforcée dans l’établissement, formation continue obligatoire, évaluation régulière."},{"id":"528-1047","c":"8039","t":"Mise en place d’un corps unique d’enseignants contractuels, recrutés sur concours avec des missions élargies et des perspectives de carrière attractives."},{"id":"528-1048","c":"8039","t":"Recentrement de l’Éducation nationale sur le tronc commun obligatoire (6-16 ans), l’éveil (1-6 ans) étant confié aux communes dans une logique de subsidiarité."},{"id":"528-1049","c":"8039","t":"Renforcer les lycées professionnels et les CFA en les liant aux entreprises et aux besoins de l’économie locale. L’ouverture et la fermeture des formations sera décidée au niveau local, en fonction des débouchés réels."},{"id":"528-1050","c":"8039","t":"Créer des classes d’excellence en mathématiques et en sciences dans chaque académie."},{"id":"528-1051","c":"65","t":"Développer les structures d’alphabétisation et les cours de langue française pour les personnes non francophones."},{"id":"528-1052","c":"65","t":"Repérer les personnes en situation d’illettrisme par des actions nationales et annuelles, et leur proposer une remise à niveau gratuite."},{"id":"528-1053","c":"65","t":"Ouvrir 500 000 places en crèche et modes de garde adaptés sur 5 ans."},{"id":"528-1054","c":"65","t":"Geler les ouvertures de places du secteur privé lucratif et réorienter les financements vers l’ouverture de places dans le public."},{"id":"528-1055","c":"65","t":"Garantir la gratuité des crèches publiques."},{"id":"528-1056","c":"65","t":"Réduire partout les effectifs par classe pour faire mieux que la moyenne en Europe, qui est actuellement à 19 élèves par classe, en priorisant les maternelles et les classes des actuelles REP."},{"id":"528-1057","c":"65","t":"Renforcer les dispositifs de rattrapage scolaire."},{"id":"528-1058","c":"65","t":"Étendre la scolarité obligatoire à 18 ans, en proposant, si nécessaire, une garantie d’autonomie à partir de 16 ans."},{"id":"528-1059","c":"65","t":"Garantir la variété des langues vivantes enseignées et leur apprentissage dès le CP."},{"id":"528-1060","c":"65","t":"Augmenter le nombre de classes pour les élèves primo-arrivants."},{"id":"528-1061","c":"65","t":"Suspendre l’expérimentation de l’uniforme."},{"id":"528-1062","c":"65","t":"Mettre fin aux groupes de niveau au collège."},{"id":"528-1063","c":"65","t":"Refuser de conditionner l’entrée du lycée à l’obtention du Diplôme national du Brevet (DNB) et supprimer les classes préparatoires à la seconde."},{"id":"528-1064","c":"65","t":"Mettre en œuvre un plan de construction d’établissements publics dans les déserts d’écoles publiques."},{"id":"528-1065","c":"65","t":"Rattraper le gel du point d’indice depuis 2010 et revaloriser les grilles salariales en engageant une négociation avec les organisations syndicales et mettre fin au Pacte enseignant."},{"id":"528-1066","c":"65","t":"Renforcer partout les effectifs de la vie scolaire (assistants d’éducation, assistants pédagogiques)."},{"id":"528-1067","c":"65","t":"Créer un service public d’accompagnement du handicap, avec un nouveau corps de personnels fonctionnaires et mettre fin à la mutualisation des accompagnants d’élèves en situation de handicap."},{"id":"528-1068","c":"65","t":"Renforcer la médecine scolaire en garantissant le nombre de personnels par établissement."},{"id":"528-1069","c":"65","t":"Établir le diplôme national du baccalauréat, abroger les contre réformes du lycée, de la voie professionnelle et du collège."},{"id":"528-1070","c":"65","t":"Abroger la loi Carle (enseignement privé)."},{"id":"528-1071","c":"65","t":"Appliquer un malus au financement public des établissements privés sous contrat."},{"id":"528-1072","c":"65","t":"Intégrer l’enjeu écologique dans les programmes de la maternelle au lycée et introduire de nouveaux enseignements pratiques."},{"id":"528-1073","c":"65","t":"Porter l’alimentation dans les cantines scolaires à du 100 % biologique et locale, réduire la part des protéines carnées au profit des protéines végétales et imposer une option végétarienne quotidienne."},{"id":"528-1074","c":"65","t":"Étendre le droit de réunion et d’association pour les lycéens."},{"id":"528-1075","c":"65","t":"Interdire les diplômes privés professionnels."},{"id":"528-1076","c":"65","t":"Rétablir le baccalauréat professionnel en quatre ans, abroger les contre-réformes du lycée professionnel en renforçant notamment les enseignements généraux et en supprimant les nouvelles périodes de stage."},{"id":"528-1077","c":"65","t":"Permettre l’accès et la gratuité des places d’internat aux étudiants et apprentis mineurs sous condition de ressources et pour les plus éloignés des lieux d’apprentissage."},{"id":"528-1078","c":"65","t":"Réserver la taxe d’apprentissage aux établissements publics."},{"id":"528-1079","c":"65","t":"Rehausser le niveau d’investissement public dans la recherche."},{"id":"528-1080","c":"65","t":"Abroger l’augmentation des frais d’inscription décidée par Macron pour les étudiants étrangers."},{"id":"528-1081","c":"65","t":"Renforcer les grands instituts publics de recherche (CNRS, Inserm, Inrae, etc.), garants des recherches d’intérêt général et supprimer l’Agence nationale de la recherche."},{"id":"528-1082","c":"65","t":"Supprimer le Crédit impôt recherche au profit du financement des universités et instituts de recherche et mettre en place des plans nationaux de recherche."},{"id":"528-1083","c":"65","t":"Instaurer la gratuité de l’enseignement supérieur, de la licence au doctorat, quelle que soit la nationalité des étudiants."},{"id":"528-1084","c":"65","t":"Supprimer la contribution à la vie étudiante et de campus (CVEC)."},{"id":"528-1085","c":"65","t":"Interdire le caractère lucratif des écoles privées de l’enseignement supérieur (actionnariat, cotation en bourse)."},{"id":"528-1086","c":"65","t":"Construire 15 000 logements supplémentaires par an pour les étudiants, rénover et remettre aux normes de sécurité et environnementales les logements existants."},{"id":"528-1087","c":"7805","t":"Donner plus d'autonomie aux chefs d'établissements en matière de discipline, de méthodes, d'horaires, d'uniforme, de choix et d'évaluation des enseignants."},{"id":"528-1088","c":"7805","t":"Augmenter de 20 % en moyenne le salaire des enseignants sur un quinquennat pour le ramener au moins au niveau de la moyenne européenne."},{"id":"528-1089","c":"7805","t":"Créer un service public universel du soutien scolaire, combinant assistant IA personnalisé et brigades d'anciens professeurs et d'étudiants volontaires."},{"id":"528-1090","c":"7805","t":"Adapter les rythmes scolaires aux besoins des enfants : journées moins longues, plus de sport et de culture, vacances d'été raccourcies pour éviter la déperdition des savoirs."},{"id":"528-1091","c":"7805","t":"Concentrer l'enseignement primaire sur les savoirs fondamentaux, lire, écrire, compter."},{"id":"528-1092","c":"7805","t":"Réviser le recrutement, la formation et l'accompagnement des professeurs tout au long de la carrière."},{"id":"528-1093","c":"7803","t":"Revaloriser les salaires des professeurs.\n+135 €/mois net en début de carrière, +300 €/mois net au cœur de la carrière financés sans nouveaux impôts."},{"id":"528-1094","c":"7803","t":"Une Ecole Normale du Professorat par académie : concours régionalisé après la licence, formation de cinq ans sur le terrain, et une voie ouverte aux talents venus du privé (ingénieurs, cadres, artisans...)."},{"id":"528-1095","c":"7803","t":"Recentrer l'école primaire sur les fondamentaux : 15 minutes de lecture par jour."},{"id":"528-1096","c":"7803","t":"Créer une instance indépendante qui évalue et certifie chaque établissement (public comme privé)."},{"id":"528-1097","c":"7803","t":"Donner plus d'autonomie aux directeurs d'établissement."},{"id":"528-1098","c":"7803","t":"Restaurer le mérite et l'exigence : instaurer un examen d'entrée en 6ème, revaloriser le bac, refonder Parcoursup au seul mérite."},{"id":"528-1099","c":"7803","t":"Étendre l'éducation prioritaire aux campagnes oubliées."},{"id":"528-1100","c":"7803","t":"Instaurer un programme « zéro écran » : interdire l’usage du téléphone jusqu’à la fin du lycée et faire signer un contrat d’engagement aux familles."},{"id":"528-1101","c":"7803","t":"Renforcer l’autorité à l’école en instaurant des sanctions claires contre le harcèlement et les violences envers les enseignants et les dépositaires de l’autorité de l'Etat."},{"id":"528-1102","c":"7803","t":"Apprendre aux élèves à se servir de l'IA."},{"id":"528-1103","c":"7803","t":"Faire une «filière d’excellence» de l’enseignement professionnel, accessible dès 14 ans, pilotagée par les régions et les entreprises."},{"id":"528-1104","c":"7803","t":"Créer 1 000 établissements publics gratuits et autonomes d’ici 2032, dotés d’une liberté accrue dans leur organisation pédagogique et la gestion de leurs moyens, en contrepartie d’une évaluation régulière de leurs résultats."},{"id":"528-1105","c":"8038","t":"Augmenter de 15 % les salaires des enseignants, en plus de l’inflation, sur la durée du quinquennat."},{"id":"528-1106","c":"8038","t":"Réduire à 19 le nombre maximum d’élèves par classe dans les écoles primaires."},{"id":"528-1107","c":"8038","t":"Intégrer davantage de savoirs pratiques à l’école, notamment la cuisine, le jardinage, le bricolage, le théâtre, les arts plastiques et la musique, avec des modules pratiques réguliers."},{"id":"528-1108","c":"8298","t":"Donner davantage de visibilité et de garanties aux habitants des communes rurales sur le maintien de classes dans les écoles, en suspendant la fermeture des écoles rurales sans l’accord du maire."},{"id":"528-1109","c":"8298","t":"Pour la fin du primaire, instaurer un certificat de fin d’études."},{"id":"528-1110","c":"8298","t":"Remettre en place des parcours cohérents et lisibles en restaurant les trois filières scientifique, littéraire et économique au lycée."},{"id":"528-1111","c":"8298","t":"Interdire l’écriture inclusive jusque dans l’enseignement supérieur."},{"id":"528-1112","c":"8298","t":"Créer un ministère d’État du Savoir et de la Transmission."},{"id":"528-1113","c":"8298","t":"Mettre un terme au collège unique en instituant des classes de niveaux."},{"id":"528-1114","c":"8298","t":"Étendre l’enseignement du latin et du grec à tous les établissements du territoire national."},{"id":"528-1115","c":"8298","t":"Suspendre les allocations familales des parents d’élèves perturbateurs ou absentéistes."},{"id":"528-1116","c":"8298","t":"Transformer les Conseillers Principaux d’Éducation en Surveillants Généraux ayant pour but exclusif le maintien de l’ordre scolaire au sein des établissements."},{"id":"528-1117","c":"8298","t":"Créer des internats de réinsertion pour les élèves perturbateurs."},{"id":"528-1118","c":"8298","t":"Rendre le port de la blouse obligatoire au primaire."},{"id":"528-1119","c":"8298","t":"Supprimer les INSPE en les remplaçant par des Écoles Normales Supérieures Régionales."},{"id":"528-1120","c":"8298","t":"Revaloriser les salaires des enseignants en accélérant la progression des carrières et en attribuant des Primes d’Excellence Professorale fondées sur la qualité de la transmission du savoir évaluée grâce à de plus fréquentes inspections."}]},{"id":"1136","name":"Enseignement supérieur","ideas":[{"id":"1136-1121","c":"7806","t":"Repenser Parcoursup à travers une concertation des parents, étudiants, universités et acteurs de l'éducation."},{"id":"1136-1122","c":"7806","t":"Renforcer l'accompagnement personnalisé pour l'orientation des élèves en amont de Parcoursup."},{"id":"1136-1123","c":"7806","t":"Conduire un grand “bilan” de l’autonomie des universités pour proposer un modèle de financement renforcé, durable et lisible, garantissant aux universités les moyens de remplir pleinement leurs missions d’enseignement et de recherche."},{"id":"1136-1124","c":"7806","t":"Améliorer l'encadrement de l'enseignement supérieur privé lucratif : transparence des financements, contrôle pédagogique renforcé, aides publiques conditionnées."},{"id":"1136-1125","c":"7806","t":"Réduire les inégalités géographiques dans l'accès aux études supérieures : création d'une aide nationale pour compenser les frais liés à l'éloignement, développement de formations délocalisées."},{"id":"1136-1126","c":"7806","t":"Réinventer les bourses étudiantes avec un véritable droit à la formation : ouvrir un chantier ambitieux avec les syndicats et les universités pour créer un capital formation universel, allocation activable à tout moment de la vie."},{"id":"1136-1127","c":"7806","t":"Rénover les bâtiments et campus universitaires, avec priorité à l’efficacité énergétique et à la biodiversité pour des campus adaptés au climat de demain, favorisant un climat d’étude serein."}]}]},{"id":"493","name":"Défense","subs":[{"id":"635","name":"Défense & armées","ideas":[{"id":"635-1128","c":"7804","t":"Renforcer nos Armées."},{"id":"635-1129","c":"7804","t":"Protéger l'Europe."},{"id":"635-1130","c":"10536","t":"Construire 2 nouveaux porte-avions."},{"id":"635-1131","c":"10536","t":"Passer de 15 à 20 frégates de premier rang."},{"id":"635-1132","c":"10536","t":"Augmenter la flotte opérationnelle de Rafale de 250 à 300."},{"id":"635-1133","c":"10536","t":"Transformer la réserve opérationnelle en une véritable garde nationale de 100 000 réservistes."},{"id":"635-1134","c":"10536","t":"Instaurer un service national civique obligatoire de 3 mois avec option militaire d'une année."},{"id":"635-1135","c":"10536","t":"Enterrer le SCAF et se concentrer sur le successeur du Rafale."},{"id":"635-1136","c":"10536","t":"Mettre l'accent sur notre souveraineté et notre autosuffisance en matière de production de matériel militaire."},{"id":"635-1137","c":"10536","t":"Renforcer la place de l'Etat dans les grands groupes de défense."},{"id":"635-1138","c":"7806","t":"Accélérer la production industrielle pour faire face à un conflit de haute intensité sur le sol européen, signer des contrats à moyen et long termes avec nos industriels, mobiliser l’ensemble du tissu industriel, des grands groupes aux PME et start-ups."},{"id":"635-1139","c":"7806","t":"Lancer de grands programmes de production de drones, de modernisation de nos capacités spatiales et travailler à l’intégration de l’IA dans notre outil de défense."},{"id":"635-1140","c":"7806","t":"Lancer un grand programme « cyber sentinelle » : des brigades spécialisées dans la lutte contre la cybercriminalité seront déployées dans tout le pays, appuyées par des centres régionaux et le renforcement de l’ANSSI."},{"id":"635-1141","c":"7806","t":"Augmenter drastiquement la réserve opérationnelle."},{"id":"635-1142","c":"7806","t":"Mettre en place un fonds européen de défense de 500 Mds€ via un emprunt commun."},{"id":"635-1143","c":"7806","t":"Proposer à nos partenaires de l’UE d’étendre la dissuasion nucléaire française aux autres pays de l’Union européenne, en conservant la souveraineté française sur la décision d’emploi."},{"id":"635-1144","c":"7806","t":"Piloter politiquement la production comme les exportations d’équipements militaires."},{"id":"635-1145","c":"7806","t":"Augmenter drastiquement l’aide militaire à l’Ukraine : protéger le ciel de l'Ouest et du Centre de l'Ukraine contre les missiles russes. Saisir les 210 milliards d'avoirs publics russes gelés en Europe pour les affecter à l'aide à l'Ukraine."},{"id":"635-1146","c":"7806","t":"Se libérer de notre dépendance américaine : réserver les fonds européens aux productions européennes pour ne plus se défendre en achetant des armes américaines et construire notre autonomie stratégique."},{"id":"635-1147","c":"8413","t":"Continuer à livrer des armes à l'Ukraine : livrer les missiles scalp, les mirages 2000."},{"id":"635-1148","c":"10767","t":"Investir dans la cybersécurité, la cryptographie quantique et post quantique, dans les drones."},{"id":"635-1149","c":"65","t":"Mettre en place une conscription citoyenne de neuf mois, pour les femmes et les hommes de moins de 25 ans, rémunérée au SMIC – revalorisé – ; elle comprend une formation militaire initiale."},{"id":"635-1150","c":"65","t":"Abroger le SNU."},{"id":"635-1151","c":"65","t":"Lutter contre la course à l’armement spatial tout en garantissant la souveraineté de la France face aux nouvelles menaces."},{"id":"635-1152","c":"65","t":"Se retirer du commandement intégré de l’OTAN."},{"id":"635-1153","c":"65","t":"Adopter une loi de programmation militaire visant à restaurer notre indépendance, notre souveraineté industrielle et mettre en œuvre notre adaptation au changement climatique."},{"id":"635-1154","c":"7805","t":"Porter le nombre de réservistes de 45 000 à 250 000 et le service militaire volontaire de 3000 à 50 000 places par an."},{"id":"635-1155","c":"7805","t":"Massifier notre production et nos achats de drones tactiques, sur le modèle du programme américain de 300 000 drones."},{"id":"635-1156","c":"7805","t":"Lancer un grand plan munitions pour dépasser l'objectif actuel de 100 000 obus par an et atteindre l'échelle des 700 000 produits par l'Allemagne."},{"id":"635-1157","c":"7805","t":"Renforcer notre flotte navale, notamment en doublant le nombre de navires aux Antilles pour lutter contre le narcotrafic et sécuriser nos Outre-mer."},{"id":"635-1158","c":"7805","t":"Lancer une nouvelle loi de Programmation militaire (LPM) de la massification, au delà de la LPM actuelle, qui épaissit les armées sans les étendre."},{"id":"635-1159","c":"7803","t":"Lancer un livre blanc sur la défense."},{"id":"635-1160","c":"7803","t":"Consolider les fondamentaux par une dissuasion nucléaire entretenue et modernisée."},{"id":"635-1161","c":"7803","t":"Mettre en place un modèle d’armée complet."},{"id":"635-1162","c":"7803","t":"Renforcer les munitions et les missiles de longue portée."},{"id":"635-1163","c":"7803","t":"Se tourner vers l’IA et les drones."},{"id":"635-1164","c":"7803","t":"Reconstruire une armée de réserve territorialisée avec la dotation d’au moins 100 000 réservistes à terme."}]}]}]};
